window.BC=window.BC||{};window.BC.meta={"CAISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL": "Coal", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["NP15", "SP15", "ZP26"]}, "ERCOT": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"]}, "MISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["MISO-East", "MISO-Illinois", "MISO-Indiana", "MISO-Plains", "MISO-South", "MISO-West"]}, "NEISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Boston", "Central", "Connecticut", "North"]}, "NYISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "years": [2023, 2024, 2025], "zones": ["Capital_Hudson", "Long_Island", "Lower_Hudson", "NYC", "Upstate_West"]}, "PJM": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "COAL_WC": "Coal Waste", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"]}};window.BC.manifest=[{"date": "2026-06-24", "definition": "(DIAGNOSTIC; keeper stays neiso-29) neiso-29 + OTHER residual class vintage-carry (2025 OTHER 2.61->2.78 TWh, measured EIA-923 like biomass): small correct fix (C1 +3.64->+3.56, C2 +3.0%->+2.5%). Solved on current main, so it also surfaces a8b0e55 (CC nameplate ~75%->92%) dropping NEISO prices 13-18% into under-prediction (C3a -15.9/-14.0/-8.1%) and storage -76% -- a SEPARATE NEISO CC-availability item, not the biomass/OTHER work.", "file": "frontend/data/backcast/runs/2026-06-24-neiso-30-other-carry.js", "id": "2026-06-24-neiso-30-other-carry", "iso": "NEISO", "label": "neiso 30 other carry", "shorthand": "neiso-30-other-carry", "years": [2023, 2024, 2025]}, {"date": "2026-06-25", "definition": "NEISO CC_REGULAR committed min-load tranche re-anchored 0.92->1.27 (=econ_high) per measured CAMPD min-stable-load HR (1.30x avg vs full-load 0.93x); min-load priced at-or-above full-load SRMC, removes wall-masked cheap min-load block. a8b0e55 kept ON. vs neiso-30.", "file": "frontend/data/backcast/runs/2026-06-25-neiso-31-cc-minload.js", "id": "2026-06-25-neiso-31-cc-minload", "iso": "NEISO", "label": "neiso 31 cc minload", "shorthand": "neiso-31-cc-minload", "years": [2023, 2024, 2025]}, {"date": "2026-06-25", "definition": "vs neiso-31: dispatch-identical (CC min-load 1.27 re-anchor, a8b0e55 ON, biomass must-run, OTHER vintage-carry, measured AGT daily gas overlay all unchanged). Change is a BENCHMARK/attestation reconcile of NEISO solar: model & benchmark both on EIA-930 grid basis (already via actuals_source); documents that EIA-923 ISNE SUN (3.70/4.53 TWh) includes ~2.8-3.2 TWh distribution-connected/net-metered BTM PV netted into the EIA-930 net-load demand series, excluded from both sides by construction. Energy balance unchanged.", "file": "frontend/data/backcast/runs/2026-06-25-neiso-32-btm-solar.js", "id": "2026-06-25-neiso-32-btm-solar", "iso": "NEISO", "label": "neiso 32 btm solar", "shorthand": "neiso-32-btm-solar", "years": [2023, 2024, 2025]}, {"date": "2026-06-25", "definition": "vs neiso-32 (keeper): CT AS/RUC out-of-merit deployment-floor overlay REMOVED (ct_deployment_overlay OFF); every other flag/code path byte-identical. Determination-neutral AND dispatch-neutral: the overlay only ever injected 0.076/0.041/0.054 TWh/yr (<0.1% of generation), so removing it leaves gas-family 54.23/58.81/61.60 TWh, system mean LMP 33.95/38.91/66.70 $/MWh and CO2 unchanged, and the verdict stays NOT-YET with the IDENTICAL basis (undocumented fuelmix / price_tail / storage). The overlay was the calibration log's 'most answer-injecting' measured-CEMS floor yet did not flip any gate (CT_PEAKER is structurally under-produced ~0.5-0.9 TWh/yr by the energy-only LP \u2014 a reserves/local-reliability MODEL MISS the 0.04 TWh floor never closed). Removing it is strictly cleaner per CLAUDE.md #12 (one fewer measured-outcome injection) at zero cost to the backcast.", "file": "frontend/data/backcast/runs/2026-06-25-neiso-33-no-ctfloor.js", "id": "2026-06-25-neiso-33-no-ctfloor", "iso": "NEISO", "label": "neiso 33 no ctfloor", "shorthand": "neiso-33-no-ctfloor", "years": [2023, 2024, 2025]}, {"date": "2026-06-27", "definition": "(PROBE) Priced-interchange + dual-limb weather floor: registers import/export as its own dashboard class (the fuelRows 'interchange' row, model vs EIA-930 net interchange) the same way CAISO/PJM measure it. Surfaces a real miss \u2014 the NEISO priced import/export node OVER-IMPORTS (net import model vs actual 18.1/15.1 (2023), 18.8/10.3 (2024), 27.4/8.1 TWh (2025)): the import tranches are sized to the import envelope, not calibrated to net energy, so the LP floods cheap imports and under-runs domestic gas. Keeper stays the measured-schedule run (neiso 35); priced mode needs import-tranche price/capacity calibration before it is a keeper. Carries the new temperature-correlated reliability floor (CT_PEAKER hot-limb TMAX, COAL/ST_GAS cold-limb TMIN).", "file": "frontend/data/backcast/runs/2026-06-27-neiso-34-import-export.js", "id": "2026-06-27-neiso-34-import-export", "iso": "NEISO", "label": "neiso 34 import export", "shorthand": "neiso-34-import-export", "years": [2023, 2024, 2025]}, {"date": "2026-06-27", "definition": "neiso-37 = the neiso-33 keeper recipe (measured Algonquin/EIA-MA-citygate DAILY gas-hub basis overlay + dual-fuel oil re-attribution + EIA-930-pinned hydro budget with 2024 plant-capacity backfill + biomass/OTHER measured must-run + historic outage overlay + storage vintage ramp) WITH the dual-limb temperature-correlated reliability floor (neiso_temp_reliability_floor: CT_PEAKER hot-limb on TMAX, COAL/ST_GAS cold-limb on TMIN) added on top. Restores the measured daily gas-hub basis overlay (--gas-hub-basis-daily) that neiso-36 had accidentally dropped: with only the flat MONTHLY hub, the within-month cold-day Algonquin spikes never crossed distillate parity, so the physical dual-fuel gas->oil switch never tripped, modeled oil collapsed ~1.6->0.05 TWh and relabeled back onto gas-CC (gas-family C2 +4.3%, FAIL). With the daily overlay restored the switch trips on the real cold-day prints, 2025 oil returns to 1.60 TWh and the gas family lands 60.85 vs EIA-930 59.76 (+1.8%, C2 PASS). Verdict CALIBRATED-WITH-CAVEATS: 1 HARD C1 CC_REGULAR 2023/24 gas-vs-EIA-930-OTHER fold-in categorization caveat + carried soft C3c price-tail and C5b storage caveats; C6 attested. Promotes NEISO keeper 33 -> 37.", "file": "frontend/data/backcast/runs/2026-06-27-neiso-37-weather-floor.js", "id": "2026-06-27-neiso-37-weather-floor", "iso": "NEISO", "label": "neiso 37 weather floor", "shorthand": "neiso-37-weather-floor", "years": [2023, 2024, 2025]}, {"date": "2026-06-28", "definition": "neiso-39 = the neiso-38 keeper recipe EXACTLY (measured Algonquin/EIA-MA-citygate DAILY gas-hub basis overlay + dual-fuel oil re-attribution + EIA-930-pinned hydro budget with 2024 plant-capacity backfill + biomass/OTHER measured must-run + historic CAMPD outage overlay + storage vintage ramp + the dual-limb temperature-correlated reliability floor + the neiso_floor_outage_exempt Merrimack/ST_GAS availability fix) WITH one structural-parity refactor and NO behaviour change: NEISO's gas offer curve is consolidated into a single grounded, commented _NEISO_OFFER_CURVE dict deep-merged on iso==NEISO, at parity with _PJM_OFFER_CURVE / _NYISO_OFFER_CURVE. Previously NEISO carried one scattered inline override (CC_REGULAR committed 1.27) and silently inherited the generic ERCOT-derived 'else' for every other gas band (incl. the 13.15x CT_PEAKER peak wall). Step 1 (this run) is behavior-preserving: every band is transcribed exactly from NEISO's prior effective curve, so config builds for all 7 ISOs are byte-identical AND this 3-year solve reproduces the neiso-38 keeper byte-for-byte on every metric (gas 54.19/58.72/61.42 TWh, oil 0.35/0.25/1.59, hydro 8.70/7.33/5.11, LMP 33.93/38.88/66.60). Step 2 (grounded re-level: shape from NEISO's own CAMPD HRs, cap the ERCOT-derived CT peak to ~3-4x vs the ISO-NE IMM/Potomac EMM) is deferred and documented as a follow-up. At promotion (2026-06-28) this run's determination read as calibrated-with-caveats (C2/C3a/C3b/C4/C5a/C6 PASS; C1 CC_REGULAR gas-vs-EIA-930-OTHER fold-in + C3c price-tail + C5b storage caveats carried unchanged from neiso-38). Current determination is NOT-YET: a subsequent NEISO bench refresh (accompanying the neiso-41 relfloor-rebuild run) moved the 2025 gas-family target, and neiso-39's unchanged dispatch now fails C2 system-volume (2025 gas +2.8%), which is undocumented in this bundle's exceptions ledger and so is not carried as an accepted caveat -- a benchmark-side drift, not a dispatch regression in neiso-39 itself. Promotes NEISO keeper 37 -> 39 (and lands the neiso-38 availability fix, previously only a patch file); note a newer NEISO run (neiso-41-relfloor-rebuild) already exists in the registry.", "file": "frontend/data/backcast/runs/2026-06-28-neiso-39-offer-curve.js", "id": "2026-06-28-neiso-39-offer-curve", "iso": "NEISO", "label": "neiso 39 offer curve", "shorthand": "neiso-39-offer-curve", "years": [2023, 2024, 2025]}, {"date": "2026-06-28", "definition": "(PROBE, rejected) pjm 62 coopt deliverable: pjm 61 consolidate config + energy_reserve_coopt with deliverable reserve-supply scoping (pjm_reserve_supply_cap = \u03a3 ramp10[eligible] + pjm_reserve_online_gated \u03c1=1.0). Measured PJM Primary req (~3.4 GW) vs published two-step ORDC, cleared inside the LP. RESULT: reserve cleared $0 in every hour, so prices are IDENTICAL to the pjm 61 energy-only keeper-candidate (2023 26.42/56.50, 2024 24.89/58.66, 2025 35.06/76.97 avg/max). This is the expected honest confirmation (handoff step 2): the deliverable cap is ~50 GW and online \u03c1\u00b7\u03a3P is huge \u2014 both \u226b the ~3.4 GW requirement on a ~180 GW fleet \u2014 because the perfect-foresight LP is not tight when PJM's real RT was tight. The top-tail decompression needs per-gen R[g]\u2264ramp10[g] (reserve competing with energy on the marginal unit) PLUS commitment tightening, NOT zone-aggregate scoping. Memtest correction: the zone-aggregate co-opt FITS the 15 GB box (~14.5 GB peak/yr), so the doc's prior 'cannot run any co-opt on 15 GB' claim was stale. Nothing fitted to the residual (claude.md #11).", "file": "frontend/data/backcast/runs/2026-06-28-pjm-62-coopt-deliverable.js", "id": "2026-06-28-pjm-62-coopt-deliverable", "iso": "PJM", "label": "pjm 62 coopt deliverable", "shorthand": "pjm-62-coopt-deliverable", "years": [2023, 2024, 2025]}, {"date": "2026-06-28", "definition": "(PROBE, not promoted) pjm 63 offercurve: pjm 61 consolidate energy-only config + a one-lever offer-curve reshape. CC_REGULAR econ_high 1.38->1.60 + peak 5.0->6.0 (steepen CC upper econ ramp + widen duct-firing scarcity band); CT_PEAKER committed 1.25->1.10 / econ_low 1.05->0.95 / econ_high 1.40->1.20 / peak 4.0->3.0 (lower the whole peaker curve). No reserve co-opt. RESULT: lifted the price-duration BODY ~+0.5 $/MWh avg/yr (2023 26.42->26.87, 2024 24.89->25.38, 2025 35.06->35.59 avg) but the TOP TAIL stayed flat/down (max 2023 56.50->56.46, 2024 58.66->57.57, 2025 76.97->76.83). Diagnostic: the CC duct-firing peak tranche rarely clears so widening it didn't lift the max; lowering CT_PEAKER capped the max (the CT peaker is the model's top-hour marginal/ceiling unit). Offer-curve tuning (CLAUDE.md #1 second step), nothing fitted to the residual (#11). Memory peak 11.8 GB.", "file": "frontend/data/backcast/runs/2026-06-28-pjm-63-offercurve.js", "id": "2026-06-28-pjm-63-offercurve", "iso": "PJM", "label": "pjm 63 offercurve", "shorthand": "pjm-63-offercurve", "years": [2023, 2024, 2025]}, {"date": "2026-06-29", "definition": "(PROBE) miso25 flag set + full --interchange-shaping (both legs, default percentile=90): shape the priced interchange node by the measured EIA-930 (month x hour-of-day) net-interchange envelope \u2014 import availability capped overnight-deep/midday-shallow, export min_gen released to the measured midday export. FIXES gap (1), the diurnal volatility: peak->trough swing drops to 1959/1636/1674 MW (2023/24/25) from miso25's ~4832, vs actual 1020/999/1471 \u2014 the measured deliverability envelope (admissible rule #12, same class as miso_seam_flow_limit) is the right structure and stays. BUT overcorrects the LEVEL: net imports now UNDERSHOOT actual \u2014 23.93/13.79/10.28 TWh vs actual 37.9/23.1/19.0 (miso25 overshot 46.7/32.4/21.4). Root cause is structural and documented in inject_interchange_shape: the full shape caps *gross* import availability at the *net*-import envelope (net << gross since MISO imports AND exports across different seams), starving baseload imports \u2014 the LP imports ~100% of hours (2023/24) but the per-hour cap binds low. Import depth too shallow at every percentile (2023 p10/p50/p90 -4502/-2714/-538 vs actual -7130/-4330/-1596). Collateral: 2025 coal over-runs (+26 TWh vs EIA-923) backfilling the missing imports; energy-balance drift -4.5/-4.8 TWh in 2024/25. Lever for the level is the code's designed INTERCHANGE_SHAPE_IMPORT_PCT 'bidir sweep' (fatten the deliverable overnight tail) -> miso27c (import_pct=97). NO firm floor, energy_reserve_coopt OFF.", "file": "frontend/data/backcast/runs/2026-06-29-miso27b-interchange-shape-full.js", "id": "2026-06-29-miso27b-interchange-shape-full", "iso": "MISO", "label": "miso27b interchange shape full", "shorthand": "miso27b-interchange-shape-full", "years": [2023, 2024, 2025]}, {"date": "2026-06-29", "definition": "(PROBE \u2014 REJECTED) neiso-40 = neiso-39 keeper recipe + neiso_oil_burn_budget flag ON: adds an inventory-limited monthly oil-burn LP constraint (one row per oil-primary generator \u00d7 month, upper bound = EIA-923 Schedule 5 petroleum receipts converted to MWh). Goal: produce >$300 scarcity-tail hours (C3c) by endogenously pricing marginal oil MWh when the monthly budget binds in cold-snap months. NULL FINDING: F923 petroleum receipt coverage is too sparse to support the constraint \u2014 only 1-2 NEISO plants report petroleum receipts (out of 140 oil-primary generators / 5345 MW), and in 2025 only 2/12 months have any deliveries. A sparsity guard (requires \u22656 months with deliveries AND \u22655% of fleet reporting) correctly skips the constraint in all 3 years, producing a solve identical to neiso-39. The fundamental issue: F923 receipts measure fuel deliveries to tank, not inventory available to burn \u2014 zero receipts in a month doesn't mean zero oil available (plants burn from stored inventory). Dual-fuel gas units (6831 MW) are excluded from the constraint because their oil consumption isn't captured in F923 petroleum receipts (they report as gas plants). The C3c scarcity tail requires a different mechanism \u2014 likely a forward-derivable winter fuel-inventory or delivery-logistics constraint, not monthly F923 receipts.", "file": "frontend/data/backcast/runs/2026-06-29-neiso-40-oil-budget.js", "id": "2026-06-29-neiso-40-oil-budget", "iso": "NEISO", "label": "neiso 40 oil budget", "shorthand": "neiso-40-oil-budget", "years": [2023, 2024, 2025]}, {"date": "2026-06-29", "definition": "(PROBE \u2014 not promoted; keeper stays pjm 58 seam-border) pjm 64 offercurve: pjm 63 config + ONE lever, CT_PEAKER peak 3.0->5.0 (above pjm 61's 4.0). Keeps the pjm 63 CC_REGULAR body gain (econ_high 1.38->1.60, peak 5.0->6.0) and the lower CT_PEAKER committed/econ_low/econ_high (1.10/0.95/1.20), but raises the peaker duct-firing scarcity ceiling so it clears the lifted CC upper econ ramp \u2014 letting the marginal CC set the top-tail clearing price instead of being capped by a low peaker ceiling. RESULT: lifted ONLY the 2024 max (57.57->63.03, +5.46); 2023 (56.46) and 2025 (76.83) max and ALL years' body (avg 26.87/25.38/35.59, p50/p90) unchanged to the cent \u2014 confirms the peak tranche is the binding ceiling only in 2024 and is a rarely-reached scarcity band that never moves the body. Model max ~$56-77 vs PJM actual hundreds: the top-tail miss is structurally NOT offer-curve-reachable on this energy-only LP (matches the reserve-track conclusion). Offer-curve tuning (CLAUDE.md #1 second step), not a residual adder. Energy-only, no co-opt (pjm 62 cleared reserve $0), no P2.", "file": "frontend/data/backcast/runs/2026-06-29-pjm-64-offercurve.js", "id": "2026-06-29-pjm-64-offercurve", "iso": "PJM", "label": "pjm 64 offercurve", "shorthand": "pjm-64-offercurve", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "ercot 21 cc-coal-rebalance: run157 base + reliability_floor, CC_REGULAR econ_high delta 0.0, peak delta +0.18, PRB sigmoid floor 0.74", "file": "frontend/data/backcast/runs/2026-06-30-21-cc-coal-rebalance.js", "id": "2026-06-30-21-cc-coal-rebalance", "iso": "ERCOT", "label": "21 cc coal rebalance", "shorthand": "21-cc-coal-rebalance", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "From the run157-dam-as-overlay keeper, adds reliability_floor and moderates three offer-curve deltas that caused a 2023 LMP collapse in ercot 21 ($28.57 model vs $48.36 actual at $2.54/MWh gas): CC_REGULAR econ_high delta set to -0.10 (halfway between keeper -0.20 and ercot 21 0.0), peak delta +0.25 (between keeper +0.32 and ercot 21 +0.18), and PRB sigmoid floor 0.76 (between keeper 0.78 and ercot 21 0.74). These are offer-curve shape parameters \u2014 no adder or haircut fitted to the price residual, all levers have forward analogues. Determination: NOT-YET (C1 ST_GAS 2024 fuel-mix, C2 gas 2025 system volume, and C3b price shape 2023\u20132024 remain out of band; C3a 2024 mean LMP +8.4% accepted as measured-input limitation per the attestation).", "file": "frontend/data/backcast/runs/2026-06-30-22-cc-coal-rebalance.js", "id": "2026-06-30-22-cc-coal-rebalance", "iso": "ERCOT", "label": "22 cc coal rebalance", "shorthand": "22-cc-coal-rebalance", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "ercot 23 stgas-drag-v1: ercot 22 base + gas_st_netload_drag=True (slope 0.00906, intercept -0.1376, cap 0.34)", "file": "frontend/data/backcast/runs/2026-06-30-23-stgas-drag-v1.js", "id": "2026-06-30-23-stgas-drag-v1", "iso": "ERCOT", "label": "23 stgas drag v1", "shorthand": "23-stgas-drag-v1", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "ercot 24 ct-drag-v1: ercot 23 base + ct_netload_drag=True (slope 0.00703, intercept -0.1427, cap 0.47, ramp 15-22h) + CC_REGULAR econ_high delta -0.13 (was -0.10)", "file": "frontend/data/backcast/runs/2026-06-30-24-ct-drag-v1.js", "id": "2026-06-30-24-ct-drag-v1", "iso": "ERCOT", "label": "24 ct drag v1", "shorthand": "24-ct-drag-v1", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "MISO reliability-floor rebuild: per-(zone,class) full-day day-gate (all miso23 levers retained)", "file": "frontend/data/backcast/runs/2026-06-30-miso-28-relfloor-rebuild.js", "id": "2026-06-30-miso-28-relfloor-rebuild", "iso": "MISO", "label": "miso 28 relfloor rebuild", "shorthand": "miso-28-relfloor-rebuild", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "MISO 29: fixes 3+4 + fix 1 (miso_zonal_gas_basis) + fix 2 (cc_nameplate_summer_derate)", "file": "frontend/data/backcast/runs/2026-06-30-miso-29-zonal-gas.js", "id": "2026-06-30-miso-29-zonal-gas", "iso": "MISO", "label": "miso 29 zonal gas", "shorthand": "miso-29-zonal-gas", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "MISO 30: coal sigmoid tuning (PRB sigmoid + BIT retune) + all run-29 flags restored", "file": "frontend/data/backcast/runs/2026-06-30-miso-30-cc-coal.js", "id": "2026-06-30-miso-30-cc-coal", "iso": "MISO", "label": "miso 30 cc coal", "shorthand": "miso-30-cc-coal", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "neiso-41 = the neiso-39 keeper recipe re-solved with the rebuilt generic reliability-floor engine (RELIABILITY_FLOOR_REGISTRY) replacing the legacy per-ISO injector, with 3 enabled limbs: Boston CT_PEAKER hot, Central CC_REGULAR hot, Connecticut CT_PEAKER hot (full-day day-gate, no hour-of-day windows). Monthly LMP MAE is essentially unchanged vs keeper 39: 2023 $3.78->$3.77, 2024 $4.39->$4.41, 2025 $3.90->$3.90. Determination NOT-YET: the governance gate is unattested \u2014 no calibration_attestation.json is present in the bundle \u2014 so metrics are not the blocker.", "file": "frontend/data/backcast/runs/2026-06-30-neiso-41-relfloor-rebuild.js", "id": "2026-06-30-neiso-41-relfloor-rebuild", "iso": "NEISO", "label": "neiso 41 relfloor rebuild", "shorthand": "neiso-41-relfloor-rebuild", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "PJM reliability-floor rebuild: per-(zone,class) full-day day-gate. Builds on pjm 58 (seam border keeper) with the new generic registry-driven temperature reliability floor enabled. All (zone,class) limbs with enabled=True in reliability_floor_coeffs_PJM.csv are applied: CC_REGULAR, CT_PEAKER, CT_CHP, ST_GAS, COAL hot/cold per zone. Full-day step-gate (no HB windows), physically-grounded commit_frac x min_stable_pct floors. All other levers pjm 58 verbatim.", "file": "frontend/data/backcast/runs/2026-06-30-pjm-65-relfloor-rebuild.js", "id": "2026-06-30-pjm-65-relfloor-rebuild", "iso": "PJM", "label": "pjm 65 relfloor rebuild", "shorthand": "pjm-65-relfloor-rebuild", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "pjm 66 CC/CT calibration: two coupled levers for the C1 CC over-run / CT under-run. (1) CC_REGULAR committed 0.75\u21920.87 (Manual 15 SRMC floor, Rank 3 from pjm-cc-overgen-recommendation; ERCOT keeper 0.998). (2) CT_PEAKER dispatch fix from pjm-59/61 (committed 0.8784\u21921.25, econ_low 0.8792\u21921.05) so CTs clear as peakers not baseload \u2014 the pjm-58 keeper predates this structural correction. Also: CC econ_high 1.38\u21921.50 (steepen upper ramp for miss #2), ct_intermediate_split (threshold=30%), CC peak 5.0, cc_duct_peaking_cap_pct 18%, offer_curve_smoothing_mid=0.35 (pjm-61). All coal/hydro/congestion/seam-border levers pjm-58 verbatim. Energy-only, no P2 commitment.", "file": "frontend/data/backcast/runs/2026-06-30-pjm-66-cc-ct.js", "id": "2026-06-30-pjm-66-cc-ct", "iso": "PJM", "label": "pjm 66 cc ct", "shorthand": "pjm-66-cc-ct", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "pjm 67 reliability-floor + CC/CT calibration: merges pjm-65 (reliability_floor=True, per-(zone,class) temp-gated floors) with CC/CT offer-curve rebalance. CC_REGULAR committed 0.87\u21920.95 (Manual 15 SRMC, fix 2024 cheap-gas overrun), econ_low_share 0.50\u21920.55. CT split: 8 true peakers (committed 1.10, pct_peaking 20) + 62 intermediate CTs (committed 0.90, econ_low 0.92, pct_peaking 5) via ct_intermediate_split threshold=30%. CC econ_high 1.50, peak 5.0, cc_duct_peaking_cap_pct 18%, smoothing_mid 0.35. All coal/hydro/congestion/seam-border levers pjm-58 verbatim.", "file": "frontend/data/backcast/runs/2026-06-30-pjm-67-relfloor-ccct.js", "id": "2026-06-30-pjm-67-relfloor-ccct", "iso": "PJM", "label": "pjm 67 relfloor ccct", "shorthand": "pjm-67-relfloor-ccct", "years": [2023, 2024, 2025]}, {"date": "2026-06-30", "definition": "pjm 68 hydro backfill + interchange balance: layers on pjm-67 (reliability floor + CC/CT calibration). Hydro 2025 backfill: hydro_backfill_year=2024 restores 62 non-reporting EIA-923 hydro plants from 2024, EIA-930 monthly repin corrects budget level. BTM backfill: btm_backfill_year=2024 carries 2024 class totals for plants absent from the 2025 EIA-923 early release. All offer curves / coal / congestion / seam levers pjm-67 verbatim.", "file": "frontend/data/backcast/runs/2026-06-30-pjm-68-hydro-backfill.js", "id": "2026-06-30-pjm-68-hydro-backfill", "iso": "PJM", "label": "pjm 68 hydro backfill", "shorthand": "pjm-68-hydro-backfill", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "Re-registration of the ercot_ct_drag_v1 bundle (same solve as 2026-06-30-24-ct-drag-v1: ercot 23 base + ct_netload_drag=True, slope 0.00703/intercept -0.1427/cap 0.47/ramp 15-22h LST, + CC_REGULAR econ_high delta -0.13) with an updated dashboard payload after fixing scripts/render_calibration_html.py's ERCOT guard, which previously hard-excluded ERCOT from the C3c fallback tail-hour computation; C3c now falls back to model_price_by_zone when no ORDC overlay file exists for the year, so 2025 price-tail scores instead of SKIPPED (model 6h vs actual 31h > $200, ratio 0.19x). This surfaces a CAVEAT that was previously hidden, pushing the soft-caveat count to budget. Determination: NOT-YET (caveat budget exceeded: hard 2/1, soft 3/3) \u2014 hard caveats are C1 fuel-mix CC_REGULAR/CC_CHP classification split (2023/2024) and C2 gas system volume 2025 (-3.2%, EIA-923 preliminary vintage gap); soft caveats are C3b price-shape (2023/2024) and the newly-scored C3c price-tail (2025). All caveats are pre-existing, attested measured-input limitations, not new regressions.", "file": "frontend/data/backcast/runs/2026-07-01-24-ct-drag-v1.js", "id": "2026-07-01-24-ct-drag-v1", "iso": "ERCOT", "label": "24 ct drag v1", "shorthand": "24-ct-drag-v1", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "(PROBE) capdel A/B vs keeper caiso-42: byte-faithful replay of the keeper meta.json + capacity_deliverability_limits=True as the single delta. Part A live: the calibrated 7,500 MW WECC_import simultaneous-import cap is replaced by the published branch-group MIC sum crosswalked to the WECC_import seam (16,055 / 16,452 / 16,148 MW for 2023/24/25). ATTRIBUTION vs the same-code flag-off baseline (caiso 47 capdel-arm-a): 2023-only effect \u2014 the old cap is a hard ceiling (binds 744 h, p95 = max = 7,500); released, imports peak 11.2 GW (+0.69 TWh), CAISO-zone mean LMP 65.16 -> 64.73, and the model's entire 107-hour >$200 tail collapses to 0 h (actual 21 h): the calibrated cap, not physics, generated the 2023 scarcity tail \u2014 right tail-hour count in the keeper era came from an over-tight fitted scalar (rule #1: not a real mechanism). 2024/25 strict price no-op (max |dLMP| = 0.0; import tranches bind at 4.3-6.1 GW before either cap). Neither representation matches 2023 actuals (107 h = 5.1x vs 0 h = 0x of 21 h): the published MIC sum is never approached (slack >= 4.9 GW every hour) because summed per-branch-group MICs overstate simultaneous capability (parallel WECC paths; rule #12 boundary caveat) \u2014 the true binding representation lies between the tranche build and the MIC arithmetic sum. Never a keeper; flag stays default-off.", "file": "frontend/data/backcast/runs/2026-07-01-caiso-46-capdel-probe.js", "id": "2026-07-01-caiso-46-capdel-probe", "iso": "CAISO", "label": "caiso 46 capdel probe", "shorthand": "caiso-46-capdel-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "(PROBE baseline, arm A) Byte-faithful flag-OFF replay of keeper caiso-42 meta.json on current main \u2014 the drift-isolation baseline for caiso 46 capdel-probe. Same-code A/B result: the calibrated 7,500 MW cap is a hard ceiling in 2023 (p95 = max = 7,500; binds 744 h) and generates the model's ENTIRE 107-hour >$200 tail (actual 21 h) \u2014 identical to the registered keeper, so the caiso 46 tail collapse (107h -> 0h) is 100% the MIC seam-cap release, 0% main drift. 2024/25: prices byte-identical between arms (max |dLMP| = 0.0; import tranches bind at 4.3-6.1 GW before either cap), only cost-degenerate dispatch reshuffles. CAISO-zone mean LMP 2023: 65.16 (off) vs 64.73 (on). REPRODUCED independently at ef69fc1 (fresh container, full re-solve): the registered run payload regenerated byte-identical, dashboard payload deep-equal to keeper caiso-42 for all 3 years, with the 107 h tail, 744 h cap-binding and 4,312 / 6,076 MW 2024/25 import maxima confirmed exactly. Not a keeper.", "file": "frontend/data/backcast/runs/2026-07-01-caiso-47-capdel-arm.js", "id": "2026-07-01-caiso-47-capdel-arm", "iso": "CAISO", "label": "caiso 47 capdel-arm-a", "shorthand": "caiso-47-capdel-arm", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "MISO 31: coal sigmoid retune \u2014 ceil<=1.0 for BIT/PRB/PRB_follower (coal cost doesnt follow gas; markup at dear gas was backwards)", "file": "frontend/data/backcast/runs/2026-07-01-miso-31-coal-sigmoid.js", "id": "2026-07-01-miso-31-coal-sigmoid", "iso": "MISO", "label": "miso 31 coal sigmoid", "shorthand": "miso-31-coal-sigmoid", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "CT_PEAKER committed 1.55->1.15 + COAL_BIT sigmoid ceil 0.95->0.97 on miso23 keeper. Confirmed CT under-dispatch is structural (gmModel moved <0.2 TWh/year). C2 2025 gas improved -11.6%->-1.9% (PASS). NOT-YET: C1 CC/CT/ST substitution + C2 2025 coal +10.1% are model misses requiring reserve-demand co-opt + zonal granularity.", "file": "frontend/data/backcast/runs/2026-07-01-miso-33-ct-committed.js", "id": "2026-07-01-miso-33-ct-committed", "iso": "MISO", "label": "miso 33 ct committed", "shorthand": "miso-33-ct-committed", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "MISO 34 (PROBE, not keeper): energy+reserve co-opt ON (RBDC = MSSC + 400 MW regulating, $3500/MWh VOLL max penalty \u2014 MISO's real operating-reserve design). Reserve demand is NON-BINDING at 3-zone granularity: the ~1.7 GW market-wide requirement is trivially met by aggregate headroom, so it never forces commitment. CT_PEAKER stays inert (1.8/3.1/4.0 TWh, no forcing), ST_GAS flat (11.1/12.1/11.8), scarcity tail unchanged 0 h (max $61/$60/$73 vs actual 30/37/88 h). Price LEVEL lifted +2/+3/+4 $/MWh (legitimate reserve opportunity cost; C3a -14/-17% -> ~-8%), but coal 2025 REGRESSED to +18.7% (was +10.5% in miso-31) because reserve headroom pulled off gas is backfilled by coal. Diagnosis: the intended CT/ST-forcing + tail-lift needs sub-regional/zonal reserve zones with deliverability limits, NOT a market-wide curve at 3-zone copperplate and NOT a CC offer haircut. Next workstream: finer reserve-zone granularity.", "file": "frontend/data/backcast/runs/2026-07-01-miso-34-reserve-coopt.js", "id": "2026-07-01-miso-34-reserve-coopt", "iso": "MISO", "label": "miso 34 reserve coopt", "shorthand": "miso-34-reserve-coopt", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "NEISO run 42: cap CT_PEAKER peak 13.15\u21924.0 (ISO-NE offer cap, not ERCOT ORDC) and lower committed 1.55\u21921.35 (NYISO/CAISO-grounded start hurdle)", "file": "frontend/data/backcast/runs/2026-07-01-neiso-42-ct-peak.js", "id": "2026-07-01-neiso-42-ct-peak", "iso": "NEISO", "label": "neiso 42 ct peak", "shorthand": "neiso-42-ct-peak", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "neiso-43 closes NEISO: the neiso-41 keeper recipe (rebuilt generic reliability-floor engine, gas-hub-basis-daily overlay, EIA-930 hydro budget) plus a post-solve ORDC scarcity-price overlay with ISO-NE-grounded parameters (VOLL $2000 = Tariff III.1.10.1A offer cap, MCL 1200 MW = Millstone 3 largest contingency, sigma 900 MW = ISO-NE PAF Study 2022); the overlay adds a reserve-shortage adder to econ_prices for capacity economics but leaves dispatch/LP prices unchanged. C1 fuel-mix now passes outright; the remaining C2 2025 gas +2.8% is an accepted preliminary-vintage caveat (EIA-930 gas-cell geothermal/biomass fold-in, the same categorization issue as the C1 exceptions on complete vintages, not a dispatch error), and the C3c price-tail / C5b/C5c storage caveats trace to the LP's oil-parity cap on cold-hour prices, which the overlay prices for capacity value but does not lift out of the persisted LP prices that drive C3c/C5b/C5c; C6 governance passes. RE-GATED 2026-07-04 under the extended rubric: C3b price-shape is a soft FAIL (2024 NRMSE 0.160), C7 diurnal shape FAILS (CT_PEAKER profile r 0.57-0.90 with off-peak CV ratio 0.0-0.02, the flat-floor signature, across all three years, plus 2023 ST_GAS r 0.608 / CV ratio 14.4), and C8 forced-energy share FAILS (CT_PEAKER 44.0-55.3% forced 2023-2025 on a tiny <0.15 TWh/yr class; rebuilt floors exclude the P1-dependent RA bridge, so these are lower bounds). Determination NOT-YET (deciding criteria: C3b price-shape, C7 diurnal shape, C8 forced-energy share, all outright FAILs).", "file": "frontend/data/backcast/runs/2026-07-01-neiso-43-closeout.js", "id": "2026-07-01-neiso-43-closeout", "iso": "NEISO", "label": "neiso 43 closeout", "shorthand": "neiso-43-closeout", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "pjm 69 \u2014 PJM keeper (supersedes pjm-67). LIVE DELTA vs pjm-67 is the CC/CT offer-curve rebalance: CC_REGULAR committed 0.95->1.00 (shift CC rightward), CT_PEAKER committed 1.10->1.05 (let CTs compete earlier), targeting the 2024 CC_REGULAR overshoot / CT_PEAKER undershoot. pjm-69 CC_REGULAR/CT_PEAKER: 2024 331.4/17.0 TWh, 2025 321.6/29.7 TWh. SEAM CAPS INERT: pjm_seam_flow_limit + pjm_seam_export_limit are enabled but DO NOT BIND \u2014 2025 net export stayed +38.2 TWh vs actual +18.0 (target 18-22 unmet), interchange/prices ~unchanged from pjm-68. Root cause: the per-seam (month x hod) p90 export envelope, summed across the 5 neighbors, reconstitutes ~14.9 GW avg (~full 16.3 GW TTC) vs 2.1 GW actual net export, so frac~=1 and the export min_gen floor never binds (shared border zones AEP_Ohio / Dominion further inflate the sum). A per-seam marginal-p90 cap cannot bound PJM joint net position; the aggregate simultaneous-transfer-limit fix is deferred to pjm-70. All other settings pjm-68 verbatim.", "file": "frontend/data/backcast/runs/2026-07-01-pjm-69-interchange-caps.js", "id": "2026-07-01-pjm-69-interchange-caps", "iso": "PJM", "label": "pjm 69 cc/ct rebalance", "shorthand": "pjm-69-interchange-caps", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "PJM reserve-demand co-opt (unwind CC-over/CT-under + lift scarcity tail): layers energy+reserve co-optimization onto pjm-69 verbatim. energy_reserve_coopt=True turns on the co-optimized reserve balance row (measured PJM_RTO Primary requirement + published two-step ORDC $850/$300, Manual 11 sec 4.3.3 / FERC EL19-58). pjm_reserve_supply_cap=True caps cleared reserve at the fleet's physical 10-min deliverable ramp so the ORDC step can bind instead of drawing on idle full-fleet headroom (grounded capability, not a residual fit). Targets: lift C3c scarcity tail (0->6/18/59 actual) and unwind the CC-over/CT-under merit-order inversion by forcing reserve-eligible CCs to hold deliverable headroom. All other pjm-69 settings verbatim.", "file": "frontend/data/backcast/runs/2026-07-01-pjm-70-reserve-coopt.js", "id": "2026-07-01-pjm-70-reserve-coopt", "iso": "PJM", "label": "pjm 70 reserve coopt", "shorthand": "pjm-70-reserve-coopt", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "PJM 71 coal-bit-floor 0.65 (bracket bisect): floor=0.75 overshot (COAL_BIT -8/-13 TWh under). Bisecting the 0.55-0.75 bracket at 0.65 to find the floor that best splits C1-coal-volume and C3a-price. Sigmoid: floor=0.65, ceil=1.32, gas_mid=3.40, gas_slope=2.5. All other settings pjm-70 verbatim (reserve co-opt ON).", "file": "frontend/data/backcast/runs/2026-07-01-pjm-71-coal-bit.js", "id": "2026-07-01-pjm-71-coal-bit", "iso": "PJM", "label": "pjm 71 coal bit", "shorthand": "pjm-71-coal-bit", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "(PROBE) capdel A/B vs pjm-69 (the PJM keeper at probe time; since superseded by pjm 71 coal-bit): byte-faithful replay of the keeper meta.json + capacity_deliverability_limits=True as the single delta. CONFIRMED structural no-op in the PJM backcast: the Part A seam hook never fired (CETO/CETL are internal LDA limits \u2014 no seam import_limit resolves to PJM_external) and Part B gates only evolve_fleet, which the backcast never calls (fleet dispatched as observed). Residual deltas vs the REGISTERED keeper (e.g. 2023 CC_REGULAR -5.7 TWh, 2024 LMP -10.3% vs -10.1%) are main-branch code/data drift since the keeper solved at 4437acd, not the flag \u2014 the flag-off arm-A replay on current main (pjm 73 capdel-arm-a) reproduces this run byte-for-byte (max |dMW| = max |dLMP| = 0.0 over all ~24.9M dispatch rows, all 3 years). Forecast-facing Part B root-cause note: the curated PJM 'requirement' is the LDA CETO and 'import_limit' the CETL, so headroom = (in-zone firm + CETL) - CETO screens EVERY filed LDA long (+10 to +42 GW, 2026/27) by construction \u2014 the gate degenerates to a PJM-wide capacity-payment collapse (except unfiled West_APS), while PJM's real adequacy test is CETL >= CETO (tight for SWMAAC at 1.02x). The mechanism direction is right; the CETO-as-requirement semantic is misaligned to our zone-total headroom frame. Never a keeper; flag stays default-off.", "file": "frontend/data/backcast/runs/2026-07-01-pjm-72-capdel-probe.js", "id": "2026-07-01-pjm-72-capdel-probe", "iso": "PJM", "label": "pjm 72 capdel-probe", "shorthand": "pjm-72-capdel-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-01", "definition": "(PROBE baseline, arm A) Byte-faithful flag-OFF replay of keeper pjm-69 meta.json on current main \u2014 the drift-isolation baseline for pjm 72 capdel-probe. Result: byte-identical to pjm 72 (max |dMW| = max |dLMP| = 0.0, all 3 years), proving capacity_deliverability_limits is a strict no-op in the PJM backcast; the residual deltas both runs share vs the registered pjm-69 keeper (2023 CC_REGULAR -5.7 TWh, 2024 LMP -10.3% vs -10.1%, storage discharge 4.70 vs 4.92 TWh) are main-branch code/data drift accumulated since pjm-69 solved at 4437acd. REPRODUCED independently at ef69fc1 (fresh container, full re-solve of both arms): the registered run payload regenerated byte-identical, and the same-sha flag-on/flag-off byte-diff re-verified at 0.0 across all 74,679,000 dispatch rows and 236,520 system rows \u2014 no further PJM drift f8b5dae through ef69fc1. Not a keeper.", "file": "frontend/data/backcast/runs/2026-07-01-pjm-73-capdel-arm.js", "id": "2026-07-01-pjm-73-capdel-arm", "iso": "PJM", "label": "pjm 73 capdel-arm-a", "shorthand": "pjm-73-capdel-arm", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "ercot 25 chp-floor-v1 (KEEPER): ercot 24 ct-drag-v1 base + chp_export_floor_measured (CHP steam-following grid floor = measured EIA-923 class CF x sector grid-delivery share, superseding the pooled CAMPD p2 minimum) + the rule-#13 benchmark fix (bench-side BTM now measured-input: 923 class total x chp_btm_pct, never the model's own dispatch \u2014 the old circular bench could never fail C1 for CHP classes and drifted ~19 TWh between identical solves). CC_CHP passes C1 every year (2023 -1.22 / 2024 +0.81 / 2025 +0.07 TWh); NOT-YET at hard 2/1: C1 CC_REGULAR 2023 -8.56 TWh (root cause quantified: ~4.1 TWh missing nodal/GTC curtailment + ~3.7 TWh 923-vs-930 gas basis inconsistency landing on the marginal class) and C2 gas 2025 -2.8% (preliminary-923 vintage gap, improved from -3.2%). C3b 2024 newly passes (NRMSE 0.199).", "file": "frontend/data/backcast/runs/2026-07-02-25-chp-floor-v1.js", "id": "2026-07-02-25-chp-floor-v1", "iso": "ERCOT", "label": "25 chp floor v1", "shorthand": "25-chp-floor-v1", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "(PROBE \u2014 not promoted; caiso-42 keeper stands) caiso 48 solar-decommit bridge: caiso-45 (startup bridge + bidir-intertie export sink) plus the caiso_ra_bridge_decommit control \u2014 (1) economic bridges bounded to the 24-h day-ahead commitment horizon (CAISO IFM/RUC commit one operating day; multi-day idles are next-day decommit/re-offer decisions), and (2) gap hours where the candidate min-load floors exceed the P1 import-dispatch + export-sink absorption reprice to the curtailable-renewable keep-running offer, with uneconomic bridges decommitted cheapest-startup-first (RUC order). UC physics only; nothing fitted to a residual. KEY FINDING: refutes the caiso-45 open item \u2014 the bridge adds only +0.58/-0.88/+0.14 TWh of annual gas (P2\u2212P1, 2023/24/25); the '2025 +34.4% over EIA-923' guardrail trip was the P1 BASELINE against the raw preliminary 2025 vintage (55.2 TWh, ~71% reporting); on the repaired C2 basis 2025 gas is +7.9% (improved from caiso-42's +12.3%, still a HARD FAIL). Negatives/curtailment now appear (25/148/32 negative-price hours; 2024's 148 exist already at P1 via the export sink + negative offers). NOT promoted: C1 2024 CC_REGULAR widened to +11.10 TWh (caiso-42 +9.21) \u2014 the bidir baseline raises CC infra-marginality \u2014 and 2023 >$200 tail grew to 161h vs 21h (the WECC_import 7.5 GW simultaneous-cap thread). Next levers: P1 merit order (import tranche prices / CC offers), reconciled WECC seam limit (rule #12).", "file": "frontend/data/backcast/runs/2026-07-02-caiso-48-solar-decommit.js", "id": "2026-07-02-caiso-48-solar-decommit", "iso": "CAISO", "label": "caiso 48 solar-decommit bridge", "shorthand": "caiso-48-solar-decommit", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "ercot 26 gtc-limits-v1: ercot 25 chp-floor-v1 base + measured hourly NP6-86 GTC export limits on the PNHNDL/WESTEX/NE_LOB links (ercot_gtc_limits_measured). Keeper on structural faithfulness (rule #1) but NEUTRAL on the backcast: 2023 curtailment 2.45->2.46 TWh, CC_REGULAR 133.18->133.19 \u2014 the West/Panhandle export interfaces carry ~3 GW vs ~10 GW capacity and saturate <1% of hours, so the C1 CC_REGULAR 2023 residual is confirmed nodal/intra-zone (VALEXP/McCamey/138 kV), not at the zonal interface. Determination NOT-YET (hard 2/1: C1 CC_REGULAR 2023 + C2 gas 2025, both attested; soft 3/3).", "file": "frontend/data/backcast/runs/2026-07-02-ercot26-gtc-limits.js", "id": "2026-07-02-ercot26-gtc-limits", "iso": "ERCOT", "label": "ercot26 gtc limits", "shorthand": "ercot26-gtc-limits", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "ercot 27 ordc-structure-v1 (PROBE, not promoted \u2014 keeper stays ercot26 gtc-limits). ercot 26 base + ORDC-era 2023 price-formation structure, zero fitted parameters: (1) published pre-reform ECRS deployment design (P1-LEVEL: no price-based ECRS release 2023-06-10\u21922024-07-31, at-cap demand step per IMM 2023 SOM; standing VOLL ramp from 2024-08-01 \u2014 PUCT rejected NPRR1224's $750 floor; the handoff's recalled $2,000 proxy floor does not exist in any primary source); (2) multi-product AS co-opt; (3) opt-in AS-aware P2 commitment with commitment-state-aware reserve headroom; (4) endogenous storage AS (G5). NOTE: P1 (no commitment) is the model's MAIN run; this probe opted into a P2 pass and is scored on it. VERDICT \u2014 the 2023 scarcity-month improvement is already present in P1 (Jun residual \u221223.5\u2192\u221213.9, Jul \u221210.1\u2192\u22129.7, Oct/Nov \u22480), i.e. it comes from the P1-level ECRS withholding + AS carve-outs; the AS-aware P2 pass added NO scarcity-month signal (Jun \u221213.9\u2192\u221212.9, Aug \u221288.7\u2192\u221290.2) and only a broad all-month elevation (+$11.5/yr 2023: C3a P1 \u221215.8% vs P2 +7.9%; 2024 +7.2\u2192+13.4%; 2025 +2.6\u2192+8.9%) \u2014 the exact-coverage AS-adequacy floor leaves ~1.0\u00d7 online-reserve coverage vs measured RTOLCAP ~2\u00d7 (Feb-2023 +$42.5 with ECRS not yet live isolates the artifact). The P2 route is shelved. Independently, dropping the lumped ORDC total-reserve curve (the published RTORPA mechanism) collapses even P1's deep tail (Aug-2023 \u2212$88.7 vs keeper \u2212$46; >$1000 28h vs 61). Overlay-overlap audit clean (RTORDPA/DAM-AS vs endogenous scarcity min-overlap \u2248$0.2k/$3.9k \u2014 one event one channel holds). Follow-up is P1-level: ECRS/product withholding AND the ORDC total-reserve family together. Determination NOT-YET (C1 CC_REGULAR 2023 / C2 gas 2025 inherited; C3 fails are the probe's own artifacts, deliberately MODEL MISS).", "file": "frontend/data/backcast/runs/2026-07-02-ercot27-ordc-structure.js", "id": "2026-07-02-ercot27-ordc-structure", "iso": "ERCOT", "label": "ercot27 ordc structure", "shorthand": "ercot27-ordc-structure", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "MISO 35: 6-zone zonal refinement (phase 1 of the zonal-refinement scope) \u2014 Midwest split to the six measured EIA-930 sub-BA/LRZ-union zones (West/Plains/Illinois/Indiana/East/South) with per-season hourly CIL/CEL deliverability caps from the LOLE Study Reports and the RDT one-way pair (3,000/2,500 MW) attached to Plains (D3: no spurious Plains congestion; kept). One-way link bounds newly wired (the RDT had been silently symmetric). STRUCTURAL GATES: (1) interfaces bind \u2014 RDT N-to-S 71/326/1074 h and S-to-N 3077/2033/877 h (23/24/25); West CIL 701/232/672 h; Illinois CEL 1199/541/984 h; (2) zonal prices separate \u2014 hours with spread >$1 go 0 to 2519/1467/717 (max spread $20-28) \u2014 but zone MEAN LMPs stay nearly flat and South sits ~$0.4-1.1 below Midwest (S-to-N exports of cheap South CCGT; mean-level sign check needs the D6 per-hub LMP upload to score); (3) Illinois shows near-zero local scarcity as expected; East/South import-at-limit in scarcity hours cannot fire with the scarcity tail still at 0 h \u2014 reserve co-opt deliberately OFF this run (phase 2 re-enables it, gate 4). Same offer stack as the miso-31 keeper; level metrics essentially unchanged (2025 coal +10.4% vs +10.5%; C3a -8.5/-13.7/-17.0%). Most structurally faithful MISO run.", "file": "frontend/data/backcast/runs/2026-07-02-miso-35-zonal-refinement.js", "id": "2026-07-02-miso-35-zonal-refinement", "iso": "MISO", "label": "miso 35 zonal refinement", "shorthand": "miso-35-zonal-refinement", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "MISO 36 (PROBE, wiring-bug evidence): miso-35 keeper flags + --energy-reserve-coopt, run BEFORE the run_year wiring fix. Demonstrates the flag was SILENTLY INERT for MISO on the backcast path: the co-opt dispatch-kwargs chain in run_calibration.run_year ended at NEISO, so the RBDC design (reserve_config._miso_design) was reachable only from the forecast runner. Results replicate miso-35 (energy-only LP; no reserve family, no reserve_price). Implication: miso-34's registered '+2/+3/+4 $/MWh reserve lift' was main-branch drift, not the co-opt \u2014 verified at miso-34's recorded clean sha 6712bdb (no MISO branch). Superseded by miso-37 (wired).", "file": "frontend/data/backcast/runs/2026-07-02-miso-36-coopt-flag.js", "id": "2026-07-02-miso-36-coopt-flag", "iso": "MISO", "label": "miso 36 coopt flag", "shorthand": "miso-36-coopt-flag", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "MISO 37 (PROBE): market-wide RBDC energy+reserve co-opt genuinely IN the backcast LP for the first time (new run_year MISO branch -> unchanged _miso_design; requirement MSSC+400 MW = 4,353 MW, 8 ORDC steps $437-$3,500). Honest finding at 6-zone granularity: reserve clearing price EXACTLY $0 in all 26,280 hours \u2014 the ~4.4 GW market-wide requirement never binds against tens of GW of idle eligible headroom, and congestion does not change the market-wide sum (same result as the 3-zone miso3 probe and the PJM ORDC campaign). Dispatch differs from miso-36 only by degenerate-tie reshuffling (max LMP delta $0.29). Gates 1-3 unchanged from miso-35. Requirement NOT inflated, penalty NOT raised (rules #1/#11); structure retained. Tail lever moves to the zonal families (miso-38).", "file": "frontend/data/backcast/runs/2026-07-02-miso-37-coopt-wired.js", "id": "2026-07-02-miso-37-coopt-wired", "iso": "MISO", "label": "miso 37 coopt wired", "shorthand": "miso-37-coopt-wired", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "MISO 38 (KEEPER): miso-37 + LOCATIONAL reserve family per scope \u00a76 (--miso-zonal-reserves): MISO-South zonal operating-reserve family, requirement = within-zone MSSC 3,953 MW (BPM-002 \u00a73.3.2 zonal minimum, the 'pre-determined largest zonal event'), priced at the PUBLISHED Zonal Operating Reserve Demand Curve (BPM-002 \u00a75.2.1.2 / Schedule 28-A: 20% @ $200, 70% @ $1,100, 10% @ $3,300 = VOLL - zonal reg proxy). Zero residual-fitted parameters. Gate 4 PARTIAL: the zonal family FIRES (reserve dual nonzero 266/287/875 h in 2023/24/25 \u2014 right year ordering, 2025-concentrated) but prices at re-dispatch opportunity cost ($8-21/MWh max), never at the curve steps: the LP always clears the requirement by re-dispatch, so the >$200 scarcity tail stays 0 h vs actual 30/37/88 and CT_PEAKER (5.0/8.4/8.8 TWh) / 2025 coal (212 TWh) are unchanged. Fit is unchanged vs miso-35 (mean LMP 28.65/26.06/34.74; duration-curve max lifts 54.5/62.0/70.4); keeper because strictly more structurally faithful (real co-opt + real zonal curve). Residual root cause is NOT missing reserve structure \u2014 perfect-foresight headroom; next levers: sub-shortage opportunity-cost band (per-gen ramp rows, memory-infeasible at plant scale) or the D6 per-hub LMP scoring once uploaded. GATE 2 SCORED vs D6 hub actuals (2026-07-02, docs/multi-iso/miso-zonal-gate2.md): PARTIAL/FAIL/PARTIAL. The South-below-Midwest sign is REAL (actual RT S-minus-Midwest -2.39/-3.20/-4.96 vs model -1.09/-0.55/-0.32) and RDT S->N binding hours carry real timing skill vs actual South-cheapest hours (lift 1.5-2.4x, precision to 92%) \u2014 but the five Midwest zone means are identical to the cent (pairwise mean-order agreement 10/5/5 of 15; the actual Indiana/East premium and the high-wind West discount, W-E -5 to -7, are absent), spread-duration is 1-2 orders under on every tier even vs DA, and the non-RDT CIL/CEL groups mostly bind DEGENERATELY (West CIL at cap 1152/238/661 h with $0 price effect). Root cause: LOLE island envelopes are adequacy-scale quantities, an order of magnitude above where real Midwest flowgates (MWEX, IN->MI, WUMS) price; next levers are published flowgate limits on L1-L6, the D1 Michigan split, and marginal-loss factors. Keeper standing unchanged (no more-faithful run exists; nothing tuned to the residual).", "file": "frontend/data/backcast/runs/2026-07-02-miso-38-zonal-reserves.js", "id": "2026-07-02-miso-38-zonal-reserves", "iso": "MISO", "label": "miso 38 zonal reserves", "shorthand": "miso-38-zonal-reserves", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "PJM 74 CC/CT offer rebalance (planned as run-72): one Manual-15-grounded step along the pjm-69 axis. CC_REGULAR econ_low 0.92->1.00 (composite-cost floor: LP has no no-load variable, M15 cost recovery puts every increment >= 1.0x full-load AHR fuel). CT_PEAKER econ_high 1.40->1.27 (M15 Sec 2.3 10% cost adder cap on worst-tranche IHR ~1.15x -> ceiling ~1.27; 1.40 exceeded the cost cap). CC committed stays 1.00 (at/past M15 min-load floor; committed raises are year-uniform and would break clean 2023 CC); CT peak block untouched (scarcity/tail out of scope per pjm-reserve-ordc Phase 1-2 gate). All else pjm-71 verbatim (coal_bit floor 0.65, reserve co-opt ON). RESULT: PJM keeper (supersedes pjm-71; most structurally faithful \u2014 two uncited offer values replaced by M15-derived ones). CC down ~-4.4 TWh ALL years (year-uniform), CT +1.0..+1.8: 2024 CC_REGULAR +20.9->+16.6 TWh, CT_PEAKER -9.7->-8.8 (both still C1 FAIL), 2025 CC +4.9->+0.3; 2023 CC -2.3->-6.7 (NEW C1 volume fail \u2014 the cost of removing the below-cost band). Prices all improved: C3a 2024 -9.4->-8.7%, 2025 -14.8->-14.1%, C3b 2025 0.208->0.204, C2 2025 gas +4.1->+3.4% (coal +2.6->+3.4%). C6 PASS (attested). Verdict NOT-YET. The 2024-concentrated CC-over/CT-under residual is NOT reachable by year-uniform offer multipliers \u2014 root cause is the missing commitment tightening / per-gen reserve structure (pjm-reserve-ordc Phases 1-2); offer retune along this axis is exhausted.", "file": "frontend/data/backcast/runs/2026-07-02-pjm-74-cc-ct.js", "id": "2026-07-02-pjm-74-cc-ct", "iso": "PJM", "label": "pjm 74 cc ct rebalance", "shorthand": "pjm-74-cc-ct", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "PJM 75 CT net-load deployment drag + CC demonstrated-peak cap. CT_PEAKER min-gen floor clip(0.01108*netGW - 0.9987, 0, 0.46) in ramp h[15,22) \u2014 measured CAMPD CT CF vs EIA-930 net-load (derive_pjm_ct_netload_drag.py), the ERCOT/CAISO keeper mechanism with PJM-fit hinge coefficients; forward-native replacement for the diagnosed AS/RUC deployment energy. CC capacity capped at CAMPD demonstrated sustained max (p99.9, 2023-25) for 17 plants whose nameplate exceeds it >1.1x (-2686 MW phantom top-band; derive_cc_capacity_reconcile.py --iso PJM --mode cap, EIA-923 feasibility-guarded). All else pjm-74 verbatim (M15 offer moves, coal_bit floor 0.65, reserve co-opt ON, commitment=False). RESULT (NOT-YET, new PJM keeper): both CT_PEAKER C1 fails cleared (2024 -8.76 -> -4.48 TWh now in band; 2023 +2.49 in band); 2024 CC_REGULAR halved +16.57 -> +8.85 TWh/+0.8pp (still FAIL); 2023 CC -6.71 -> -14.54 TWh (accepted cost: the cap removes phantom capacity the 2023 fit leaned on); C2 2025 gas +3.4 -> +2.7%, coal +3.4 -> +4.2%; C3a 2024 -8.7 -> -8.1%, 2025 -14.1 -> -13.4%; C3b/C4/C5a/C6 PASS; C3c 0 tail hours unchanged (blocked on per-gen reserve thread). Deltas vs pjm-74 near-uniform (CC -7.5..-7.9, CT +4.0..+4.5 TWh/yr): the floor overlaps hours the LP already dispatched, so the year-differentiation is milder than the floor energy (4.7/6.3/7.2 TWh) implied.", "file": "frontend/data/backcast/runs/2026-07-02-pjm-75-ct-drag.js", "id": "2026-07-02-pjm-75-ct-drag", "iso": "PJM", "label": "pjm 75 ct-drag cc-cap", "shorthand": "pjm-75-ct-drag", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "HEAD re-gate (calibration-complete checklist item 1): byte-faithful replay of ercot32-ordc-total-rtolcap meta.json at HEAD, all keeper years in one invocation, verifying reproducibility across the 07-04 offer merges per the pjm-77/nyiso-48 pattern.", "file": "frontend/data/backcast/runs/2026-07-03-32-head-regate.js", "id": "2026-07-03-32-head-regate", "iso": "ERCOT", "label": "32 head regate", "shorthand": "32-head-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) caiso 49 perhub seam: measured-hub WECC seam \u2014 per-hub signed corridors (Malin->NP15, Palo Verde->SP15) each priced at its own measured OASIS intertie LMP (import = hub + OATT wheel + per-tranche CARB border carbon; export = hub), measured p95 corridor deliverability envelopes BOTH directions, published branch-group MIC seam import limit (16,055/16,452/16,148 MW) replacing the audit-flagged fitted 7,500 MW scalar, 2023 Jan-Feb OASIS gap reference-formula-filled. All caiso-42 keeper levers carried. Fair-calendar verdict: C3b 0.325/0.479/0.454 (keeper 0.321/0.516/0.536), C2 2025 gas +7.3% (was +12.3%), C4 2025 gas r 0.533 (was 0.416), C3c 2023 88h (was 107h fitted-cap artifact) \u2014 but C3a 2023/24 worsened (+26.7/+38.5% vs +16.9/+36.9%): pricing EVERY tranche at spot transplants hub spikes into CAISO whenever the tie is marginal, while the real market's contracted import majority is inframarginal. Superseded by caiso-51.", "file": "frontend/data/backcast/runs/2026-07-03-caiso-49-perhub-seam.js", "id": "2026-07-03-caiso-49-perhub-seam", "iso": "CAISO", "label": "caiso 49 perhub seam", "shorthand": "caiso-49-perhub-seam", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) caiso 50 perhub bridge: caiso-49 measured-hub seam + the caiso-44/48 startup-cost-aware RA bridge with DA-horizon decommit (UC restart economics \u2014 hold a committed CC at min-load when startup cost exceeds the net hold cost). Improves caiso-49 on every price criterion (C3a +24.9/+35.9/+42.4; C3b 0.305/0.446/0.442; C4 gas r 0.805/0.565) and collapses the 2023 fitted-cap tail 88h -> 11h (0.52x of actual 21h \u2014 the committed fleet stops leaning on hub-spiked spot imports at tight hours). C1 2024 CC_REGULAR +10.87 TWh is the standing hard-gate miss (fall/winter under-import). Superseded by caiso-51 (adds the firm-contract seam decomposition).", "file": "frontend/data/backcast/runs/2026-07-03-caiso-50-perhub-bridge.js", "id": "2026-07-03-caiso-50-perhub-bridge", "iso": "CAISO", "label": "caiso 50 perhub bridge", "shorthand": "caiso-50-perhub-bridge", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "KEEPER caiso 51 firm base: the structurally complete WECC seam decomposition \u2014 firm/contracted tranches (BPA firm hydro over COI, desert-SW solar PPAs over Path-46) held at documented contract-cost estimates (inframarginal, as the real market schedules its specified-import majority), spot tranches (Mid-C economy, DSW thermal, scarcity) and both export legs at the measured hourly Malin/Palo Verde hub, measured p95 deliverability envelopes both directions, published MIC seam import limit (16.0/16.5/16.1 GW) replacing the fitted 7,500 MW cap, UC startup bridge/decommit, EIA-930 monthly hydro budgets, and every caiso-42 lever. Fair-calendar verdict NOT-YET, best CAISO to date: C3a +19.6/+34.9/+41.6% (keeper caiso-42: +16.9/+36.9/+47.1), C3b NRMSE 0.285/0.459/0.436 (best), C4 2023 gas passes (r/NRMSE in band, first time), C2 2025 gas +8.1% (was +12.3%), C5a 2025 +8.7% (was +12.7%). Standing misses: C1 CC_REGULAR +4.91/+10.86 TWh (fall/winter under-import: 2024 net import 25.8 vs 32.4 TWh actual \u2014 the specified-import VOLUME is under-represented; needs CEC/CARB specified-imports data intake), spring-midday floor ~$34-38 vs actual ~$11-14 (model short where reality is RUC-long and exporting), C3c tail honest-collapsed 0h (the old 107h tail was a fitted-cap artifact, caiso-46/47). Promoted on structure (rules #1/#14): removes the fitted flat import ladder and the fitted 7,500 MW cap from the binding path. RE-GATED 2026-07-04 under the extended rubric (C7 diurnal shape / C8 forced-energy share, audit D-1/D-2): still NOT-YET, and now FAILS C7+C8 on the CT class (CT_PEAKER off-peak CV ratio 0.03-0.06 \u2014 the flat-floor signature \u2014 and 27-33% of CT energy at binding non-exempt floors; ST_GAS profile r also below gate). Confirmed by the successor probe caiso-52-ct-scrub (S2), the OPEN SCRUB THREAD for this keeper: removing the CT forcing stack fixes the shape (CV ratio 2.6-3.3, off-window 0%) but exposes the real evening-CT merit-order root cause (P1 import tranche prices / CC offers, caiso-48 next-levers) \u2014 the floor was fitting the class. caiso-51 stays keeper on seam structure until the merit-order root cause lands; do not win the CT class back with a floor (rules #1/17-20). HEAD-DRIFT DIAGNOSED (2026-07-06, issue #1346 / gap G-11): these committed numbers are PRE-SCRUB and unreproducible on any post-07-03 main \u2014 PR #1279 (caiso-52 CT scrub: 916e8cb bridge physics-gate, 77c4f67/b3a9036 limb window+retire) legitimately removed the overnight CT floor energy this bundle carries (CT ~3.4\u2192~1.7-2.1 TWh, C8 27-33%\u219260-71% on re-solve; shared-input hashes identical, code not data). A keeper re-solve/re-gate under scrubbed main is owed (with use_plant_emission_rates_v2=True per the L-8 memo \u00a79.6); no clean candidate exists until the ramp/LCR evening-merit build lands.", "file": "frontend/data/backcast/runs/2026-07-03-caiso-51-firm-base.js", "id": "2026-07-03-caiso-51-firm-base", "iso": "CAISO", "label": "caiso 51 firm base", "shorthand": "caiso-51-firm-base", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "PROBE (S2 CT-floor scrub; keeper stays caiso-51): remove the CAISO CT forcing stack, keeping every caiso-51 seam/hydro/outage lever. CT_PEAKER/CT_CHP all-24h netload reliability-floor limbs retired (A/B vs hour-windowed limbs: redundant with ct_netload_drag on the same driver/hours/class \u2014 one mechanism per phenomenon), leaving the net-load drag (h15-21) as the single evening CT commitment mechanism; RA bridge eligibility gated on min_down_hours >= 4 physics so fast-start CTs are never economically bridged overnight. Fixes the audit's flat-floor signature: D-1 CT off-peak CV ratio 0.03 -> 2.6-3.3 (r .886/.847/.681), D-4 off-window 65% -> 0%, CT forced energy now one windowed mechanism (bridge CT share <1%). Disclosed cost (rule #1, not to be won back by a floor): CT volume 1.97/1.56/1.15 vs measured 3.08/3.30/1.65 TWh, CC_REGULAR +6.2/+11.9 TWh, C3a +21.1/+36.5/+43.9%, 2023 tail 114h vs 21h. D-2 forced share 66-78% still fails: evening CT merit dispatch is the open root cause (P1 merit order: import tranche prices / CC offers, caiso-48 next-levers).", "file": "frontend/data/backcast/runs/2026-07-03-caiso-52-ct-scrub.js", "id": "2026-07-03-caiso-52-ct-scrub", "iso": "CAISO", "label": "caiso 52 ct scrub", "shorthand": "caiso-52-ct-scrub", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-caiso-statmode-d-7.js", "id": "2026-07-03-caiso-statmode-d-7", "iso": "CAISO", "label": "caiso statmode d 7", "shorthand": "caiso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE \u2014 NOT a keeper swap) CO2-rate re-gate diagnostic: current-code (HEAD) re-solve of keeper caiso-51-firm-base, isolating the R2 physical-HR emission_rate_co2 basis (base_hr, fff2c34). CO2 vs eGRID: 2023 29.15 Mt (-2.6%, PASS), 2024 29.80 (+3.4%, PASS), 2025 28.52 (+5.2%, PASS) \u2014 all PASS vs the keeper's +0.5%/+8.4% FAIL/+8.6% FAIL. No other criterion regressed (C2 gas 2025 +8.1->+5.3%). ATTRIBUTION (ablation twin, current code with old tr_hr basis): the FAIL->PASS is ~entirely from post-07-03 CAISO offer merges (Lever B firm-import grounding etc.), NOT the emissions estimator \u2014 R2's ISOLATED effect is only +0.2-0.4 Mt (~+0.5-1%, slightly WORSE, still PASS). Conclusion: R2 does not break CAISO's CO2 verdict; keeper is stale vs 07-04 merges (owner re-gate call). Rules #1/#3/#22: no retune, holdouts untouched.", "file": "frontend/data/backcast/runs/2026-07-03-caiso51-co2re-probe.js", "id": "2026-07-03-caiso51-co2re-probe", "iso": "CAISO", "label": "caiso51 co2re probe", "shorthand": "caiso51-co2re-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "ercot 28 ordc-total-v1 (PROBE, P1-ONLY, not promoted). ercot 26 base + the P1 combined stack: multi-product AS co-opt + published ECRS conservative-deployment design + the NEW lumped ORDC total-reserve family (RTORPA, NPRR568/OBDRR048) as an all-class reserve-balance family drawing on every product's cleared reserve (dispatch reserve_class -1) - product withholding and the total-reserve curve price TOGETHER for the first time (the ercot27 named follow-up) - + endogenous storage AS (G5). No P2/AS-aware commitment (shelved). VERDICT: the total family restores deep tail (2023 >$500 58 vs ercot27-P1 28) and 2025 tail 0.19x->0.26x, but 2023 collapses vs keeper (C3a -11.0%, Aug -76.4 vs -46.1) - ROOT-CAUSED to the G5 endogenous split holding 2.1-2.4x the measured battery AS award (2023: 2,625 vs 1,249 MW mean; it lacks the published ECRS 2-h / Non-Spin 4-h duration requirements), flooding the total-reserve curve. 2024 C3a +7.5/shape 0.209; C1/C2 unchanged (CC_REGULAR 2023 -8.5, gas 2025 -3.0%). Determination NOT-YET.", "file": "frontend/data/backcast/runs/2026-07-03-ercot28-ordc-total.js", "id": "2026-07-03-ercot28-ordc-total", "iso": "ERCOT", "label": "ercot28 ordc total", "shorthand": "ercot28-ordc-total", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "ercot 29 ordc-total-gasshape-v1 (PROBE, P1-ONLY, not promoted). ercot 28 + the measured Henry Hub monthly gas SHAPE, level-preserving (gas_hh_monthly_shape - the Run-77 reconciled variant; the generic climatological shape held Feb/Mar-2024 ~$0.7/MMBtu too dear, Jan-2024 $0.66 too cheap). VERDICT: every month moves toward gas-cost truth (Feb-2024 +6.6 -> +3.2, Mar/Apr/Jun/Dec-2024 tighten; 2025 C3a +2.7 -> +1.6) and rule #14 keeps it; it EXPOSES two non-gas over-pricings: Jan-2024 +14.1 -> +18.1 (truthful dearer Jan gas stacking on the DAM-AS overlay's DA-boundary premium) and Feb/Mar-2025 +3 -> +5/+6 (open root-cause thread). Same endogenous-storage artifact as ercot28 (2023 Aug -74.6). Determination NOT-YET.", "file": "frontend/data/backcast/runs/2026-07-03-ercot29-ordc-total-gasshape.js", "id": "2026-07-03-ercot29-ordc-total-gasshape", "iso": "ERCOT", "label": "ercot29 ordc total gasshape", "shorthand": "ercot29-ordc-total-gasshape", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "ercot 30 ordc-total-measstor-v1 (REJECTED PROBE, P1-ONLY - the measured decomposition step). ercot 28 with the measured battery AS power reservation (storage_as_commitment) in place of the endogenous split, but WITHOUT requirement netting in 2023 and WITHOUT the product credit: reserving the award out of the storage cap while the product families still demand the full published plan over-withholds thermal by exactly the awarded MW. 2023 blows up (+87.1% C3a, Aug +159.3, tail 1.35x over), 2024 +36.8%, 2025 +22.9% - the quantified internal-consistency requirement. Superseded by ercot31/32's consistent netting; registered per rule #15 (every run on the dashboard). Determination NOT-YET.", "file": "frontend/data/backcast/runs/2026-07-03-ercot30-ordc-total-measstor.js", "id": "2026-07-03-ercot30-ordc-total-measstor", "iso": "ERCOT", "label": "ercot30 ordc total measstor", "shorthand": "ercot30-ordc-total-measstor", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "ercot 31 ordc-total-full-v1 (PROBE, P1-ONLY, not promoted). The full measured stack: ercot 28's combined product-withholding + lumped-ORDC-total structure with the measured battery AS power reservation and CONSISTENT netting (requirements netted every year the cap is reduced, from_year 2023) + the measured award netted pro-rata off the fast products (ercot_storage_as_product_credit) + the measured HH monthly gas shape. VERDICT: lands within $2-4/mo of the endogenous split everywhere (2023 Aug -71.9 vs ercot28 -76.4; C3a -9.6 vs -11.0) - the storage channel was NOT the Aug-2023 root cause; the remaining miss is the reserve-SUPPLY definition (full-fleet phantom headroom vs measured online capability), closed in ercot32. 2024 ex-DAM-AS Jan lands -2.1 (near-perfect with truthful gas). C5c 2024 storage shape r -0.306 -> +0.331. Determination NOT-YET.", "file": "frontend/data/backcast/runs/2026-07-03-ercot31-ordc-total-full.js", "id": "2026-07-03-ercot31-ordc-total-full", "iso": "ERCOT", "label": "ercot31 ordc total full", "shorthand": "ercot31-ordc-total-full", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "ercot 32 ordc-total-rtolcap-v1 (KEEPER, P1-ONLY). The faithful pre-RTC+B price-formation stack, all published/measured, zero fitted parameters: multi-product AS co-opt (measured ASPLANNP433) + published ECRS conservative-deployment design (no-release at-cap step 2023-06-10..2024-07-31, standing ramp after) + the lumped ORDC total-reserve family (RTORPA, NPRR568/OBDRR048) drawing on every product's reserve + the MEASURED RTOLCAP/RTOFFCAP reserve-supply cap (G1) so the total family prices the MEASURED reserve level, its dual added post-solve as the additive RTORPA (RTSPP = SCED energy + ORDC(online reserves); product duals are MCPCs, never in the energy price) + measured battery AS reservation with consistent netting + product credit + measured HH monthly gas shape + measured RTORDPA and DAM-AS overlays (per-column persisted; ex-overlay 2024 tail 10/53 proves the DA-priced acute days still need the overlay channel). C3 vs keeper ercot26: 2023 Jun -23.5->-13.5, Sep +5.6->-4.5, Aug -46.1->-62.4 (deep tail >$500 68/104; the residual is the flat ORDC sigma fallback vs the egress-blocked NP6-576-ER seasonal params + sub-2-day forced outages outside the >=2-day CAMPD detector); 2024 Feb +6.2->+3.2 (measured gas), Jan +12.5->+18.2 (the DAM-AS overlay's DA-boundary premium vs the RT benchmark: overlay hours realized DA ~$599 vs RT ~$205 - documented boundary misalignment, MODEL MISS not excused); 2025 tail 0.19x->0.32x, C5c storage shape r -0.306->+0.331. C1/C2 hard-caveat pair inherited unchanged (CC_REGULAR 2023 -8.53 TWh nodal/intra-zone; gas 2025 -3.0% preliminary vintage). Keeper on structural faithfulness (rule #1): strictly more real market structure than ercot26, every mechanism published or measured. RE-GATED 2026-07-04 under the extended rubric (C7 diurnal shape / C8 forced-energy share): C7 passes; C8 FAILS \u2014 2023 CT_PEAKER 11.1% forced (0.707 of 6.3579 TWh; rebuilt floors exclude the P1-dependent RA bridge, so this is a lower bound). Determination NOT-YET (C1+C2 exceed the hard budget; C3a/b/c MODEL MISS with named root causes; C8 forced-energy share now also FAILS).", "file": "frontend/data/backcast/runs/2026-07-03-ercot32-ordc-total-rtolcap.js", "id": "2026-07-03-ercot32-ordc-total-rtolcap", "iso": "ERCOT", "label": "ercot32 ordc total rtolcap", "shorthand": "ercot32-ordc-total-rtolcap", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "MISO 39 (KEEPER): miso-38 + 10-MINUTE RESERVE DELIVERABILITY (--miso-reserve-pergen): per-asset reserve columns at (zone, fuel-class) pooling (30 R columns/h; the documented 15 GB memory tier \u2014 per-plant is memory-infeasible at MISO scale), joint sum P + R <= sum pmax*availability per pool-hour, R capped at the availability-scaled 10-min class ramp (FleetArrays.ramp10 = NREL/TP-5500-55588 ramp rates x pmax: coal 0.15, CC 0.40, CT/oil 1.00, ST-gas 0.20; hourly, so CAMPD-outaged units contribute no ramp). Reserve now competes with energy on the marginal pool AND cleared reserve is bounded by what converts to energy inside MISO's 10-minute contingency window (BPM-002) \u2014 the deliverability structure the miso-38 gate-4 diagnosis named. Zero residual-fitted parameters. RESULT (gate 4 CLOSED-NEGATIVE, empirical): the >$200 tail stays 0 h vs actual 30/37/88 \u2014 the bind-gate predicted South deliverable-reserve shortfalls in 59/63/207 h (hitting 28/38 of 2025's actual DA-tail hours), but the perfect-foresight LP relieves every one by re-dispatch/import re-timing at <= $23/MWh (South thermal trim ~100 MW mean in the 207 reserve-active 2025 h); the zonal family fires MORE (59/64/207 h nonzero vs 37/41/125, max $11/$11/$23 vs $8/$11/$21) but never reaches the $200 step. Fit/volumes byte-comparable to miso-38 (mean LMP 28.62/26.04/34.74; CT_PEAKER 4.96/8.43/8.79 TWh; all deltas <0.05 TWh). KEEPER because strictly more structurally faithful (real deliverability rule added, nothing removed, nothing tuned). CONCLUSION for the tail residual (docs/multi-iso/miso-scarcity-tail-diagnosis.md): 2023's tail is 100% single-hour RT transients (DA median $40 in those hours, DA tail 1 h) \u2014 out of hourly-deterministic representation; the DA-visible part (1/24/38 h) needs the commitment-posture workstream (perfect-foresight re-timing is the binding relief channel) and/or a Midwest locational family for the 2024 Winter Storm Heather block; no admissible supply-side reserve structure can price it at this resolution. Determination NOT-YET (C1 2024 CC/CT, C2 2025 coal +10.4%, C3 price level -8.5/-13.6/-16.9% \u2014 all pre-existing, unchanged vs miso-38).", "file": "frontend/data/backcast/runs/2026-07-03-miso-39-reserve-pergen.js", "id": "2026-07-03-miso-39-reserve-pergen", "iso": "MISO", "label": "miso 39 reserve pergen", "shorthand": "miso-39-reserve-pergen", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) Cross-ISO band de-leakage (audit C-11/C-13, rule #24): MISO's inherited ERCOT gas bands (CC_CHP, CT_CHP, ST_GAS, and the CT_PEAKER committed 1.55 / econ 1.27/1.98 'generic shape') are neutralized to 1.0; MISO-grounded CC_REGULAR (committed 1.20 part-load premium, flat 0.95/1.08 baseload econ), the MISO offer-cap CT peak 4.0, and the physical F-class CC duct-burner peak 2.25 are kept; *_INTERMEDIATE (measured-shape) and coal untouched. EFFECT vs keeper miso-39 (not re-tuned, rule #1): dropping the ERCOT 1.55 CT start-hurdle to 1.0 lets peakers run, so the CT_PEAKER under-run SHRINKS -20.5->-12.0 TWh (2023) / -18.2->-9.2 (2024); the cheaper neutral bids lower C3a mean LMP to -9.8/-15.7/-19.6% (was -8.5/-13.6/-16.9%). PRE-EXISTING MISO root causes unchanged by this scrub: the CC_REGULAR +44 TWh over-run (measured-flat econ body) and the 0-hour scarcity tail (missing RDC/ELMP co-opt) \u2014 both open items, not band-addressable.", "file": "frontend/data/backcast/runs/2026-07-03-miso-40-band-deleak.js", "id": "2026-07-03-miso-40-band-deleak", "iso": "MISO", "label": "miso 40 band deleak", "shorthand": "miso-40-band-deleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper miso_39_reserve_pergen (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-miso-statmode-d-7.js", "id": "2026-07-03-miso-statmode-d-7", "iso": "MISO", "label": "miso statmode d 7", "shorthand": "miso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) Cross-ISO band de-leakage (audit C-11/C-13, rule #24): NEISO's inherited ERCOT gas bands (CC_CHP, CT_CHP, CT_PEAKER econ 1.27/1.98, ST_GAS 0.81/1.05/1.40/4.20) are neutralized to 1.0; NEISO-grounded CC_REGULAR (neiso-46) and CT start-hurdle 1.35 / offer-cap peak 4.0 / physical F-class CC duct-burner 2.25 kept. EXPECTED REGRESSIONS vs keeper neiso-43 (not re-tuned back, rule #1): C3a mean LMP regresses to -6.6% (2023, was PASS) and C2 2025 gas +3.2% as the neutral gas bids lower the stack; C3b price-shape actually improves (2024 NRMSE fail clears). OPEN ROOT CAUSE: NEISO-grounded per-class CT/gas heat-rate spreads + the ISO-NE reserve-scarcity overlay carry the price level, not the removed ERCOT ramp.", "file": "frontend/data/backcast/runs/2026-07-03-neiso-44-band-deleak.js", "id": "2026-07-03-neiso-44-band-deleak", "iso": "NEISO", "label": "neiso 44 band deleak", "shorthand": "neiso-44-band-deleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "Calibration run from bundle neiso44_base.", "file": "frontend/data/backcast/runs/2026-07-03-neiso-44-base-control.js", "id": "2026-07-03-neiso-44-base-control", "iso": "NEISO", "label": "neiso 44 base control", "shorthand": "neiso-44-base-control", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "Calibration run from bundle neiso45_flat.", "file": "frontend/data/backcast/runs/2026-07-03-neiso-45-flat-econ.js", "id": "2026-07-03-neiso-45-flat-econ", "iso": "NEISO", "label": "neiso 45 flat econ", "shorthand": "neiso-45-flat-econ", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "Calibration run from bundle neiso46_joint.", "file": "frontend/data/backcast/runs/2026-07-03-neiso-46-fast-start.js", "id": "2026-07-03-neiso-46-fast-start", "iso": "NEISO", "label": "neiso 46 fast start", "shorthand": "neiso-46-fast-start", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "neiso-47 (KEEPER; scored CALIBRATED-WITH-CAVEATS run-verdict at promotion under the 2026-07-02 re-balanced rubric \u2014 the first ISO to reach a passing determination there \u2014 but RE-GATED 2026-07-04 under the extended rubric to NOT-YET, see the re-gate note at the end): the neiso-43 closeout recipe (measured daily AGT/MA-citygate gas-hub basis + dual-fuel oil re-attribution + EIA-930-pinned hydro budget with 2024 backfill + biomass/OTHER measured must-run + historic CAMPD outage overlay + dual-limb temperature reliability floor + floor-class outage exemption + ISO-NE-grounded post-solve ORDC overlay) PLUS two coupled offer-side changes derived from the named month/hour C3b-2024 causes (Jan/Feb flat all-hours winter over-shoot +$9-10: marginal implied HR ~10.5 vs actual ~8.2 at $3.5-7.7 hub gas; Jul/Aug afternoon/evening DA-visible under-shoot -$10-11: the HR-multiplier stack collapses to ~$33 at $1.8 gas while the real fast-start margin offers $60-100): (1) --tranche-startup-amortization, fast-start tranche pricing (ISO-NE Market Rule 1 / Order 825 analogue) \u2014 the fast-start-eligible tranches (CT econ+peak; CC duct/quick-response peak band) carry the existing NREL start cost amortized over their own P0 run lengths, the fuel-price-INVARIANT offer component the multiplier curve cannot express; CC econ blocks excluded (their starts are NCPC uplift, not LMP); (2) CC_REGULAR econ band re-anchored 1.06->1.27 generic to 1.00->1.15, level from the directly-observable winter marginal implied HR (~8.2 on Salem Harbor base 7.38 -> mid-band ~1.08). Probe chain registered: neiso-44 base control (2024 C3b 0.160 FAIL), neiso-45 flatten-only (C3b 0.132 but C3a 2023 -6.2%), neiso-46 v1 all-tranche markup (CC-econ markup re-inflates mild winter, C3b 0.1518). RESULT: C3b 0.130/0.143/0.054 and C3a -4.6/-2.3/+1.8% all PASS; C1 PASS; fuel mix byte-comparable (CC_REGULAR +/-0.2 TWh vs base); storage throughput recovers ENDOGENOUSLY 0.74 -> 1.05 TWh 2025 with no storage knob (C5b -49.3%, ledgered caveat, downstream of the winter fuel-inventory item); C3c tail 0h vs 15/8/20h ledgered (closable only via the documented winter fuel-inventory build); C2 2025 gas +3.0% preliminary-vintage hard caveat (1/1); C5c SKIPPED (actual monthly PS discharge near-uniform, CV 0.137 \u2014 degeneracy guard, volume scored by C5b). Verdict: caveats 2/2 soft + 1/1 hard, every caveat ledgered in calibration_attestation.json. RE-GATED 2026-07-04 (S5, extended rubric): now NOT-YET on the two new HARD criteria alone \u2014 C7 diurnal shape FAILS (CT_PEAKER off-peak CV ratio 0.0-0.08 all three years \u2014 the flat-floor signature \u2014 plus 2023 ST_GAS profile r 0.59) and C8 forced-energy share FAILS (CT_PEAKER 44-55% of class energy at binding non-exempt floors; gate <10%). Every previously-scored criterion is unchanged (C1 passes; the C2/C3c/C5b/C5c caveat set stands). The CT commitment floor stack is the open root cause \u2014 same class of finding as the CAISO caiso-52 CT scrub; fix the floor windows/merit order, never re-tune to win C7/C8 back (rules #1/17-20).", "file": "frontend/data/backcast/runs/2026-07-03-neiso-47-fast-start.js", "id": "2026-07-03-neiso-47-fast-start", "iso": "NEISO", "label": "neiso 47 fast start", "shorthand": "neiso-47-fast-start", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "STALE (pre-R2, 2026-07-03) \u2014 superseded by 2026-07-05-neiso-statmode-d7-r2, re-solved at HEAD against the current neiso-48-ct-floor keeper after the R2 physical-HR CO2 basis (fff2c34, merged 2026-07-05) moved NEISO's carbon-priced merit order (this probe also predates the neiso-48 CT-floor-scrub keeper promotion). Retained for history, not the current D-7 gap. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper neiso_closeout (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-neiso-statmode-d-7.js", "id": "2026-07-03-neiso-statmode-d-7", "iso": "NEISO", "label": "neiso statmode d 7", "shorthand": "neiso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE \u2014 NOT a keeper swap) CO2-rate re-gate diagnostic: current-code (HEAD) re-solve of keeper neiso-47-fast-start, isolating the R2 physical-HR emission_rate_co2 basis. CO2 model ~identical to the keeper (2023 20.97 / 2024 22.72 / 2025 23.93 Mt vs keeper 20.96/22.72/23.92) \u2014 R2's isolated effect on NEISO CO2 is ~0; all years PASS as before, no criterion changed. Confirms the emissions estimator does not move NEISO's CO2 verdict. Rules #1/#3/#22: no retune, holdouts untouched.", "file": "frontend/data/backcast/runs/2026-07-03-neiso47-co2re-probe.js", "id": "2026-07-03-neiso47-co2re-probe", "iso": "NEISO", "label": "neiso47 co2re probe", "shorthand": "neiso47-co2re-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "Control probe for nyiso-41: the nyiso-39 keeper config re-solved on the corrected measured gas data only, no new mechanism \u2014 true-date placement of the Transco Z6 NY daily hub quotes (the Jan-2024 $23.90 print lands on the 16th, not the 12th) plus the NYISO monthly hub levels recomputed from the completed daily print series (Dec-2024 basis +0.16 -> +1.00 $/MMBtu). Isolates the gas-data share of nyiso-41's price gains: C3a 2024 -19.2 -> -16.3%, C3b 2024 NRMSE 0.304 -> 0.248; C3c unchanged 0h. C5a CO2 2024 -7.2% (band +/-7) appears here too, showing the marginal breach comes from the corrected data, not the import mechanism. NOT-YET; the keeper is nyiso-41.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-40-truedate-gas.js", "id": "2026-07-03-nyiso-40-truedate-gas", "iso": "NYISO", "label": "nyiso 40 truedate gas", "shorthand": "nyiso-40-truedate-gas", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "nyiso-41 takes the nyiso-40 measured-gas fidelity fixes (true-dated Transco Z6 NY daily quotes; monthly hub levels recomputed from the completed daily series) and adds one structural mechanism: nyiso_import_hub_prices reprices the priced import node's PJM_west / ISONE_tie tranches at the measured hourly PJM / ISO-NE Day-Ahead system LMP plus the $1 inter-control-area wheeling hurdle, replacing keeper-39's static per-year IMPORT_TRANCHES_BY_YEAR ladder (a backcast fit re-fitted per year, blind to neighbor fundamentals) with a measured neighbor price-formation input read blind to NYISO's own flow. Every price criterion moves toward actual with no tuned constant \u2014 C3a mean LMP -15.6/-19.2/-13.2% -> -13.3/-13.4/-9.5%, C3b NRMSE 0.211/0.304/0.203 -> 0.209/0.236/0.172, C3c price-tail hours 0h -> 7h in 2025 (the first NYISO model tail hours ever) \u2014 while C1/C2/C4/C6/C7 hold PASS. RE-GATED 2026-07-04 under the extended rubric: C8 forced-energy share FAILS all three years \u2014 CT_PEAKER 46.0-49.1% forced and ST_GAS 42.7-64.5% forced (rebuilt floors exclude the P1-dependent RA bridge, so these are lower bounds). Determination: NOT-YET (deciding criterion: C8 forced-energy share is an outright HARD FAIL, superseding the pre-existing soft-caveat picture \u2014 C1/C2 hard criteria hold 0 caveats, soft 4/2, i.e. C3a/C3b/C3c price caveats plus a C5a CO2 caveat already exceeded the 2-soft-caveat budget before C8 was added); promoted as the newest, most structurally faithful NYISO run, replacing nyiso-39.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-41-hub-prices.js", "id": "2026-07-03-nyiso-41-hub-prices", "iso": "NYISO", "label": "nyiso 41 hub prices", "shorthand": "nyiso-41-hub-prices", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) Cross-ISO band de-leakage (audit C-11/C-13, rule #24): NYISO's CT_PEAKER econ ramp (was ERCOT-fitted 1.27/1.98) and inherited CT_CHP bands are neutralized to 1.0, and the uncited ERCOT 13.15x $5,000-ORDC CT peak wall is killed -> 4.0 (NYISO offer cap; promotes the NEISO-42 precedent). NYISO-grounded CC/ST_GAS curves kept. EXPECTED REGRESSIONS vs keeper nyiso-41 (not re-tuned back, rule #1): C3a mean LMP falls to -16.9/-16.2/-13.8% (was -13.3/-13.4/-9.5%) and C1 2024 ST_GAS -3.43 TWh as the neutral (cheaper) CT econ bids lower the merit order and displace steam. OPEN ROOT CAUSE: the price level the ERCOT bands were propping up needs NYISO-grounded CT heat-rate spreads + reserve-scarcity pricing, not a re-borrowed ERCOT ramp.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-42-band-deleak.js", "id": "2026-07-03-nyiso-42-band-deleak", "iso": "NYISO", "label": "nyiso 42 band deleak", "shorthand": "nyiso-42-band-deleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "Calibration run from bundle nyiso42_iroquois_spread.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-42-iroquois-spread.js", "id": "2026-07-03-nyiso-42-iroquois-spread", "iso": "NYISO", "label": "nyiso 42 iroquois spread", "shorthand": "nyiso-42-iroquois-spread", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE \u2014 FLAGGED, NOT a keeper swap) HEAD re-gate re-solve of keeper nyiso-41-hub-prices at git 8d46b90 (byte-faithful meta replay, all years 2023-2025). Determination NOT-YET. REPRODUCES THE REGRESSION flagged in co2-keeper-regate-2026-07-05: vs keeper, CT_PEAKER energy roughly DOUBLES (2023/24/25 4.46/4.51/4.73 TWh vs actual 2.26/2.13/2.84) and ST_GAS under-runs (6.15/7.58/9.30 vs 8.70/11.07/15.99). C1 free-class 9/10 (was 10/10); C7 diurnal (D-1) FAIL (2024 CT_PEAKER off-peak CV ratio 0.454 < 0.5 \u2014 de-leaked peakers run flat overnight instead of peaky). ROOT CAUSE: the run's offer_curve_by_group is NOT in meta.json, so the replay picks up HEAD's B-NYI-1 (2026-07-05) _NYISO_OFFER_CURVE de-leak \u2014 CT_PEAKER peak 13.15->4.0 and econ_low/econ_high 1.27/1.98->1.0/1.0, CC_REGULAR econ_high 1.21->1.0 (rule-25 cross-ISO-leak neutralizations). At neutral 1.0x offers the efficient downstate LM6000 peakers (HR ~9-10) undercut the ST_GAS steam fleet (eff HR 11-12) and dispatch near-baseload. Isolated by the nyiso-49-offer-ab twin (HEAD code + keeper offer restored -> C1 10/10, C7 PASS, CT_PEAKER back to 1.56/1.37/1.75): the ENTIRE regression is the offer de-leak, NOT the emissions R2 basis or any other HEAD merge. The de-leaked (grounded) offer is correct (rule #14/#25); the ungrounded 13.15x/1.98 wall silently proxied two real missing structures \u2014 the LI/NYC delivered-fuel basis premium (downstate LM6000s priced at Transco Z6 hub, not their real citygate/interruptible gas) and #1344 reserve/RCPF scarcity price formation (reserve co-opt present but non-binding). FLAGGED FOR OWNER: keeper nyiso-41 is STALE-VS-HEAD and NOT reproducible on HEAD; do NOT promote this re-solve (fails HARD C1 free-class + C7), do NOT re-arm the de-leaked scalars (rule #26). NYISO calibration-complete item 1 is BLOCKED on the peaker-pricing structural fix. Rules #1/#3/#17/#25/#26.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-48-head-regate.js", "id": "2026-07-03-nyiso-48-head-regate", "iso": "NYISO", "label": "nyiso 48 head regate", "shorthand": "nyiso-48-head-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "STALE (pre-R2, 2026-07-03) \u2014 superseded by 2026-07-05-nyiso-statmode-d7-r2, re-solved at HEAD after the R2 physical-HR CO2 basis (fff2c34, merged 2026-07-05) moved NYISO's carbon-priced merit order. Retained for history, not the current D-7 gap. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper nyiso41_hubprices (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso-statmode-d-7.js", "id": "2026-07-03-nyiso-statmode-d-7", "iso": "NYISO", "label": "nyiso statmode d 7", "shorthand": "nyiso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE \u2014 FLAGGED, NOT a keeper swap) CO2-rate re-gate diagnostic: current-code (HEAD) re-solve of keeper nyiso-41-hub-prices, isolating the R2 physical-HR emission_rate_co2 basis. CO2 vs eGRID: 2023 25.62 Mt (-2.3%), 2024 27.43 (-6.3%, PASS vs keeper -7.2% CAVEAT), 2025 29.84 (-4.8%) \u2014 all PASS. BUT C1 fuel-mix and C7 diurnal REGRESS PASS->FAIL (ST_GAS -3.46 TWh 2024; CT_PEAKER energy ~doubles 1.82->4.41 TWh). ATTRIBUTION (ablation twin, current code with old tr_hr basis): abl == resolve on CO2 (R2 isolated effect ~0, <0.1%) AND the abl ALSO FAILs C1/C7 \u2014 so BOTH the CO2 move and the C1/C7 regression are from post-07-03 NYISO offer merges (7b891bd 'Ground the NYISO CT offer level' etc.), NOT the emissions estimator. FLAGGED FOR OWNER: keeper nyiso-41 (git 2eecf4b, 07-03) predates the 07-04 NYISO CT-offer grounding; a HEAD re-gate regresses C1/C7 and needs a deliberate NYISO re-gate \u2014 do NOT silently swap (rule #3). R2 emissions basis is safe for NYISO CO2. Rules #1/#3/#22.", "file": "frontend/data/backcast/runs/2026-07-03-nyiso41-co2re-probe.js", "id": "2026-07-03-nyiso41-co2re-probe", "iso": "NYISO", "label": "nyiso41 co2re probe", "shorthand": "nyiso41-co2re-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "PJM 76 Chesterfield outage fix: pjm-75 recipe verbatim on regenerated campd-unit-outages-PJM.csv (d815a3c). Chesterfield 3797 coal units 5/6 now carry COAL outage windows (skipped by gas overlay) instead of blocking the 386 MW surviving gas-CC. Corrects ~2.35 TWh of the pjm-75 2023 CC under-run. Also fixes Brunner Island, Chalk Point, Gilbert, Linden, Doswell outage routing. Per-gen reserve co-opt NOT included (memory-infeasible on 15 GB box; see pjm-reserve-ordc.md). All else pjm-75 verbatim (CT drag, CC cap, M15 offers, coal_bit 0.65, zone-agg reserve co-opt, commitment=False).", "file": "frontend/data/backcast/runs/2026-07-03-pjm-76-outage-fix.js", "id": "2026-07-03-pjm-76-outage-fix", "iso": "PJM", "label": "pjm 76 outage fix", "shorthand": "pjm-76-outage-fix", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper pjm76_outage_fix (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-pjm-statmode-d-7.js", "id": "2026-07-03-pjm-statmode-d-7", "iso": "PJM", "label": "pjm statmode d 7", "shorthand": "pjm-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE) caiso 53 lever-ab: tests the two FINDING-caiso-evening-merit levers on the full caiso-51 recipe. LEVER A (offer physics): CC_REGULAR/CC_CHP committed band 0.90/0.92x -> 1.00x plant-avg HR \u2014 the min-stable-load block's SRMC floor; restores committed >= econ_low ordering (econ_low held at the CAMPD-measured 0.95/0.96). LEVER B (measured market input): firm import-tranche VOLUMES grounded on DMM Annual Report RA-import capacity (CAISO BAA boundary: 2,323 MW 2023 / 3,371 MW 2024 / 2025 carries 2024 \u2014 open gap until the DMM 2025 annual report) split by published MIC branch-group share north/south of Path 15: per-year firm blocks 1072/1251, 1558/1813, 1566/1805 MW (was uncited 800/1800). RESULTS vs keeper caiso-51 \u2014 the targeted CC/import complex improves: C1 2023 CC_REGULAR now PASSES (was +4.91 TWh), 2024 +9.43 TWh (was +10.86); net import 2024 30.0 vs 32.4 TWh actual (was 25.8), 2025 38.0 vs 36.2 (was 32.3); evening corridors net-IMPORT (DSW +1213 / PNW +543 MW h15-21; the evening-export artifact is gone); C5a 2024 passes (was +8.5%); C7 CT diurnal largely fixed \u2014 2023+2024 CT_PEAKER pass, flat-floor CV signature 0.03-0.06 -> 2.6-3.1 (2025 CT fails on profile r 0.682 only; ST_GAS 2024/2025 still fail). The flagged price tension lands as expected: C3a worsens to +22.3/+37.9/+48.9% (Lever A reprices the committed band), C3b 0.303/0.488/0.502, C2 2025 gas +10.5% (was +8.1%). NEW ROOT-CAUSE ITEMS (logged, not chased): (1) 2023 C3c tail 454h >$200 vs 21h actual \u2014 Jan-2023-concentrated (513/525h): the measured $28/MMBtu citygate spike x the repriced committed CC (~$213) now crosses $200 while actual held below \u2014 monthly-average gas overlay too blunt in spike months and/or missing demand response; (2) C8 CT forced share 65-76% (was 29-33% lower-bound): forced TWh is flat (~all ct_netload_drag, 1.17-1.29 TWh) but MERIT CT energy collapsed 2.3 -> 0.6 TWh as grounded imports displace marginal CT \u2014 the drag floor now IS the CT class, confirming the FINDING's structural ramp/local gap (separate session; no floor may close it, rules #1/17-20). NOT promoted: C7 improves but C8's gated share worsens \u2014 does not beat caiso-51 on C7/C8 jointly. Both levers are grounded inputs (rule #15) and stay in code; caiso-51 remains keeper. DOF ledger: +cc_committed_hr_mult_floor (measured-physical), +caiso_firm_import_volumes (measured-market); IMPORT_TRANCHES firm volumes re-identified, n_residual 8 -> 7.", "file": "frontend/data/backcast/runs/2026-07-04-caiso-53-lever-ab.js", "id": "2026-07-04-caiso-53-lever-ab", "iso": "CAISO", "label": "caiso 53 lever ab", "shorthand": "caiso-53-lever-ab", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE) Measured daily Algonquin-Citygate gas basis (gas_hub_basis_daily) ON, mean-preserving; winter oil-inventory budget OFF. Closes the winter oil under-run endogenously: model oil 0.35/0.23/1.47 TWh (2023/24/25) vs EIA-930 0.32/0.37/1.24 (was ~0/~0/0.04 on the monthly-basis keeper), annual gas unchanged. Admissible measured delivered-fuel input (rule #13), NOT in the current keeper. Price still caps at oil parity ($258); 0 h >$300 (the tail is a scarcity-pricing question, not fuel). Also the Component-A ablation twin (inventory off).", "file": "frontend/data/backcast/runs/2026-07-04-neiso-dailybasis-oil-underrun.js", "id": "2026-07-04-neiso-dailybasis-oil-underrun", "iso": "NEISO", "label": "neiso dailybasis oil underrun", "shorthand": "neiso-dailybasis-oil-underrun", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE, INERT) Component A: winter (Nov-Mar) oil-burn inventory budget (start_fill 2.8M bbl WRP-low, +2 refills, pooled fleet row, MMBtu-weighted, dual-fuel limb gated to oil-switch hours), on top of the measured daily AGT basis. RESULT: byte-identical to the daily-basis-only twin (oil 0.35/0.23/1.47 TWh, 0 h >$300) \u2014 the ~1.5 TWh seasonal inventory never binds even with heavy oil dispatch (Jan-2025 oil 0.755 TWh < 0.91 TWh/month cap). Component A adds nothing; not tuned to force binding (rule #1). Negative result.", "file": "frontend/data/backcast/runs/2026-07-04-neiso-inventorycap-inert-probe.js", "id": "2026-07-04-neiso-inventorycap-inert-probe", "iso": "NEISO", "label": "neiso inventorycap inert probe", "shorthand": "neiso-inventorycap-inert-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "Calibration run from bundle nyiso43_ceiling_oilbasis.", "file": "frontend/data/backcast/runs/2026-07-04-nyiso-43-ceiling-oilbasis.js", "id": "2026-07-04-nyiso-43-ceiling-oilbasis", "iso": "NYISO", "label": "nyiso 43 ceiling oilbasis", "shorthand": "nyiso-43-ceiling-oilbasis", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "Calibration run from bundle nyiso44_faststart.", "file": "frontend/data/backcast/runs/2026-07-04-nyiso-44-faststart.js", "id": "2026-07-04-nyiso-44-faststart", "iso": "NYISO", "label": "nyiso 44 faststart", "shorthand": "nyiso-44-faststart", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE, NOT promoted; NOT-YET \u2014 C1-2024 ST_GAS \u22123.31 TWh + C7/C8) nyiso-44 config plus two measured CT offer-grounding mechanisms closing part of the 0c6c833 de-leak root cause: fast-start amortization v3 (NREL start cost amortized over the CAMPD-measured median start-to-stop run length, derive_campd_ct_run_lengths.py, per-plant 2\u20139 h, horizon ceiling that P0 runs may only shorten \u2014 removes the v2 self-disabling circularity) and the generator-level EIA-860 oil-primary screen (verified clean: every NYISO gas-CT bin is NG-primary at the generator level). CT_PEAKER 2024 4.75\u21924.54 TWh (actual 2.13); C3a \u221214.4/\u221214.2/\u221212.4%, C3b 0.199/0.194/0.191 (best NYISO price scores to date); C2-2025/C5a/C4/C6 PASS. First NYISO bundle scoring C7/C8 (legitimacy diagnostics committed): the nyiso-33/34 reliability floors' forced share (CT 22.6\u201328.4%, ST_GAS 34.0\u201341.5%) and the 2024 CT off-peak flatness (CV ratio 0.424) are now first-class open root causes.", "file": "frontend/data/backcast/runs/2026-07-04-nyiso-45-measuredruns.js", "id": "2026-07-04-nyiso-45-measuredruns", "iso": "NYISO", "label": "nyiso 45 measuredruns", "shorthand": "nyiso-45-measuredruns", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE, NOT promoted; NOT-YET \u2014 C1-2024 ST_GAS \u22123.31 TWh + C7/C8) nyiso-45 plus the NYSDEC 6 NYCRR 227-3 peaker-rule availability overlay: curated unit-level compliance schedule (Gold Book Tables IV-3..IV-6 2023\u20132025, per-unit citations) zeroes restricted units inside their effective ozone-season windows (phase-1 2023: Coxsackie/South Cairo/Northport GT/Port Jeff GT1/Shoreham 1&2/Glenwood GT03/74th St; phase-2 2025: Astoria GT01/Arthur Kill GT1/59th St). Availability only, never offer/price; STAR-designated Gowanus 2&3 / Narrows 1&2 barges documented but never restricted. Dispatch delta vs nyiso-45 ~nil by construction (restricted units are rarely-run oil raw units + ~50 MW small gas CTs; the big over-runners are 227-3-compliant LM6000s) \u2014 the mechanism stands on its measured regulatory basis (rule #1). Scores identical to nyiso-45; the most structurally faithful NYISO probe (best-so-far basis).", "file": "frontend/data/backcast/runs/2026-07-04-nyiso-46-decpeaker.js", "id": "2026-07-04-nyiso-46-decpeaker", "iso": "NYISO", "label": "nyiso 46 decpeaker", "shorthand": "nyiso-46-decpeaker", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper ercot_ordc_total_rtolcap_v1 (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-04-statmode-d7-probe-ercot32.js", "id": "2026-07-04-statmode-d7-probe-ercot32", "iso": "ERCOT", "label": "statmode d7 probe ercot32", "shorthand": "statmode-d7-probe-ercot32", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE) caiso 54 daily-gas: caiso-53 recipe + --gas-hub-basis-daily, testing the caiso-53 root-cause item that the MONTHLY-average SoCal/PG&E citygate gas overlay is too blunt in spike months. Intakes daily CA Composite Average citygate spot (EIA NG Weekly compact table, 2023-2025, scripts/fetch_caiso_citygate_daily.py) and replaces the flat monthly hub level with a true-calendar-dated daily shape, mean-preserving on the measured monthly basis (annual gas burn/fuel mix unchanged) -- same construction as the NYISO daily Transco leg (dense trading-day quotes), not NEISO's sparse-narrative one. RESULT (official C3c, ordc.hoursGt200, same-environment A/B vs a fresh caiso-53 reproduction): 2023 454h(monthly)->455h(daily) vs 21h actual -- essentially UNCHANGED, NOT the collapse hypothesized. Day-level attribution explains why: the daily series correctly REDISTRIBUTES the tail rather than shrinking it. The measured citygate genuinely collapsed only in the LAST WEEK of Jan-2023 ($7.80-11.50/MMBtu) -- those days correctly drop from 9-19 tail-hours/day to ZERO. But days 2-18 (measured $16-24/MMBtu) are ABOVE the monthly average once the cheap last week is excluded, so they gain tail-hours instead (max zonal LMP $219.9->up to $282.9). Net Jan effect ~505->489h (own recompute), a real but marginal ~3% reduction. CONCLUSION: the monthly-average blunting is a real, now-fixed defect (last week was wrongly priced high before), but it is NOT the primary driver of the ~450h-vs-21h over-prediction -- most of January 2023 was persistently elevated in the real citygate market, not spike-concentrated in a way a monthly average would blunt. NEW ROOT-CAUSE ITEM (logged, not chased): the dominant driver of the residual ~450h/21h gap is something else -- CT_PEAKER's ct_netload_drag floor (forced share 40-62% per this bundle's D-2) and/or ra_mustoffer_bridge are candidates, or a genuine actual-side effect (demand response / oil-switching / imports) the model lacks; investigate separately per rule #1, no floor forcing. The daily-basis input is kept in code on its own physical merits (correct day-to-day delivered fuel cost, rule #13) independent of whether it moves C3c -- a real market behaviour is not reverted because the residual didn't move (rule #1). Not promoted; caiso-51/caiso-53 remain keeper. legitimacy_diagnostics attached (D-5 caiso_ra_mustoffer gap is pre-existing/documented on caiso-53 already, not introduced here).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-54-daily-gas.js", "id": "2026-07-05-caiso-54-daily-gas", "iso": "CAISO", "label": "caiso 54 daily gas", "shorthand": "caiso-54-daily-gas", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "PROBE (W3-P2 caiso-52-ct-scrub HEAD verification; keeper stays caiso-51). Byte-faithful replay of the caiso-51 keeper config at HEAD (2026-07-05), all years \u2014 the CT-floor scrub is already merged in source, so this zero-delta replay exercises the scrubbed dispatch path and closes the flagged keeper-reproducibility 'drift'. The audit's three stacked CAISO CT forcing engines are gone, defended at three code layers: (1) reliability_floor_coeffs_CAISO.csv CT limbs windowed 15-21 then enabled=False; (2) drop_drag_owned_reliability_specs drops every CT_PEAKER limb whenever ct_netload_drag is on (rule 19); (3) RA startup bridge gated on min_down>=RA_BRIDGE_ECON_MIN_DOWN_HOURS (4h), so fast-start CTs (min-down 1h) are never economically bridged (rule 17). Result at HEAD: CT_PEAKER now a SINGLE windowed mechanism (ct_netload_drag; RA-bridge CT share <0.4% all years), D-4 off-window 0% (was ~62-66% in caiso-42), D-1 CT off-peak CV ratio 3.05-3.52 (was 0.000 flat-floor signature). Reproduces committed caiso-52 (CT 2.12/1.73/1.30 vs 1.97/1.56/1.15 TWh); the 'drift' (CT ~3.4->~1.7 TWh vs the pre-scrub keeper) IS the scrub effect, not a bug. Still open (NOT closable by a floor scrub, rule 1): D-2 CT forced share 60/67/69% > 10% = the evening-merit structural gap (CT thermodynamically dominated by CC in an energy-only zonal LP; FINDING-caiso-evening-merit \u2014 needs ramp/min-up-down + sub-zonal LA-basin structure, do NOT re-floor); D-5 caiso_ra_mustoffer w2 forecast-parity wiring gap; ST_GAS D-1 shape (pre-existing). capacity_deliverability_limits records True but no-ops (clean CAISO partition absent) so dispatch is faithful to caiso-51; MIC seam limit carried by caiso_per_hub_intertie.", "file": "frontend/data/backcast/runs/2026-07-05-caiso-55-ct-scrub.js", "id": "2026-07-05-caiso-55-ct-scrub", "iso": "CAISO", "label": "caiso 55 ct scrub", "shorthand": "caiso-55-ct-scrub", "years": [2023, 2024, 2025]}, {"ablation_twin": "Reference (limb-ON) half of the B-LIMB-1 A/B; not itself a probe subject.", "date": "2026-07-05", "definition": "(PROBE) B-LIMB-1 same-env baseline: caiso-51-firm-base on current main with the SP15/CC_REGULAR tmax reliability-floor limb ON (original CSV). Limb-ON reference for the caiso-r1-signflip-off probe; the two isolate the R1 disablement (\u0394\u22480, floor non-binding). Also documents caiso-51 keeper drift on current main: CT_PEAKER total ~1.7 TWh / C8 forced-share 60-71% vs the committed bundle's ~3.4 TWh / 27-33% (separate root-cause item).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-r1-baseline-limb.js", "id": "2026-07-05-caiso-r1-baseline-limb", "iso": "CAISO", "label": "caiso r1 baseline limb", "market_story": "Re-solving the caiso-51 keeper config on current main (limb ON) reproduces CC_REGULAR, price and CO2 within ~1% of the committed bundle but shows CT_PEAKER energy roughly halved and its C8 forced-share doubled \u2014 a keeper-reproducibility drift independent of B-LIMB-1, flagged for the CAISO owner.", "shorthand": "caiso-r1-baseline-limb", "years": [2023, 2024, 2025]}, {"ablation_twin": "D-3 zero-forcing twin deferred: the as_zero_forcing_ablation / --zero-forcing-ablation mechanism (B-DIAG-1) has not landed yet. The 2026-07-05-caiso-r1-baseline-limb run is the same-env limb-ON reference for isolating this mechanism change; register the D-3 twin once B-DIAG-1 lands.", "date": "2026-07-05", "definition": "(PROBE) B-LIMB-1 R1: caiso-51-firm-base with the unidentified sign-flip temperature-CF limb SP15/CC_REGULAR tmax DISABLED (D-8 \u00a72B: Spearman \u03c1 +0.69\u2192\u22120.10 train\u2192holdout; decision rule R1, CLAUDE.md rule 17). Same-env A/B vs the caiso-r1-baseline-limb run shows the limb was NON-BINDING: CC_REGULAR \u0394\u22640.018 TWh, CT_PEAKER/ST_GAS \u0394\u22480, price/CO2/forced-share identical \u2014 removing the unidentified floor costs ~0 dispatch. Structural change judged on identification, not fit (rule #1).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-r1-signflip-off.js", "id": "2026-07-05-caiso-r1-signflip-off", "iso": "CAISO", "label": "caiso r1 signflip off", "market_story": "The SP15/CC_REGULAR tmax reliability floor was the only live limb of the three B-LIMB-1 sign-flip limbs (PJM ComEd and CAISO SP15/ST_GAS already shipped disabled). In the caiso-51 dispatch CAISO gas-CC clears economically well above the floor's min-stable level on hot SP15 days, so the floor never bound; disabling it (R1) shifts <0.03% of CC energy. The floor was unidentified scaffolding doing no structural work \u2014 R1's best case. NOTE: the large apparent CT_PEAKER shrink vs the COMMITTED caiso-51 bundle is main-drift since 2026-07-03 (see baseline run), not this change.", "shorthand": "caiso-r1-signflip-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-caiso-statmode-d7-r2.js", "id": "2026-07-05-caiso-statmode-d7-r2", "iso": "CAISO", "label": "caiso statmode d7 r2", "shorthand": "caiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "ercot 33 ex-overlay baseline (WS-F / stage 0 of the AS co-opt overlay-replacement plan, docs/handoffs/ercot-as-coopt-plan-2026-07.md). Byte-faithful replay of keeper ercot_ordc_total_rtolcap_v1 (meta.json) with ONE delta: ercot_dam_as_overlay=False (was True). Everything else unchanged \u2014 RTORDPA overlay stays on (separate G2 backcast bridge, out of scope), multi-product AS co-opt + ECRS conservative-deployment + lumped ORDC total-reserve family + measured RTOLCAP/RTOFFCAP supply cap + measured storage AS treatment + measured HH gas shape all unchanged. Probe only, not a keeper \u2014 the clean pre-overlay baseline every later WS-A/WS-B/ercot40 stage compares against (CLAUDE.md #10/#11/#13: measurement, not calibration).", "file": "frontend/data/backcast/runs/2026-07-05-ercot33-ex-overlay-baseline.js", "id": "2026-07-05-ercot33-ex-overlay-baseline", "iso": "ERCOT", "label": "ercot33 ex overlay baseline", "shorthand": "ercot33-ex-overlay-baseline", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE, rejected \u2014 keeper stays ercot32) ercot33 offer-wall probe: measured peak-band quantile ladder, p50-clamped (derive_dam_offer_hrmults --peak-ladder; 60d DAM disclosure 2023-2025; capacity-weighted p10/p30/p50/p70/p90 of per-resource top-of-curve mult incl near-cap bids, rungs clamped from below at the class p50, top rung HCAP-clamped). Single delta vs the ercot32 keeper: the measured upper peak-band dispersion (the always-posted scarcity wall) is represented instead of collapsed to the median; every other flag byte-identical (measured GTC limits present, clean partitions regenerated from the NP6-86 archives this session). Attribution: docs/FINDING-ercot-priceshape-2026-07.md. Verdict: 2023 C3a flips to PASS (-2.9%), C8 forced-energy flips to PASS, >$500 deep tail 75/104; but the static wall over-withholds mild years (2025 C3a flips FAIL +7.7%) and the P0->P1 startup-amortization CT<->ST coupling moves ~8 TWh of mid-merit energy off the CAMPD-measured allocation (CT 10.4 vs ~6.4, ST 6.3 vs ~16.8 TWh 2023) -> C1/C2/C5c worsen. Structural conclusions filed in the FINDING doc: condition-responsive offer surface, online-capability/commitment structure, CT<->ST amortization fragility.", "file": "frontend/data/backcast/runs/2026-07-05-ercot33-offer-wall.js", "id": "2026-07-05-ercot33-offer-wall", "iso": "ERCOT", "label": "ercot33 offer wall", "shorthand": "ercot33-offer-wall", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "WS-B / G5 follow-up: run164 recipe (run157 keeper, DAM-AS overlay OFF, endogenous multi-product AS co-opt + forward requirement + RTOLCAP supply cap, P1-only) + the ONE delta ercot_storage_as_duration_gate. Adds the published per-product ESR State-of-Charge durations (RegUp/RRS 1h, ECRS 2h, Non-Spin 4h; ERCOT Nodal Protocols \u00a73.17.3/\u00a78.1) as an LP-linear, vectorized gate sum_c dur_c*RS[c,z] <= sum_{s in z} SOC[s]: storage's upward AS becomes an explicit per-zone reserve variable RS[c,z] (removed from the pooled thermal headroom), so a short-duration battery can no longer sell long-duration AS on its full power. The measured storage treatment (storage_as_commitment + ercot_storage_as_reserve + ercot_storage_as_product_credit) stays OFF \u2014 the consistent swap, never mixed (ercot30 blow-up). Cleared storage AS still counts under RTOLCAP. QUANTITY validation vs measured 60-Day DAM award: the gate cuts the endogenous over-hold from ~1.95x (run164, pooled) to 0.54/0.55/0.61x (2023/24/25) \u2014 direction corrected, closer to measured in magnitude, lands just below the 0.8-1.3x band (documented residual per CLAUDE.md #1, NOT tuned to target). Probe, not a keeper; the measured-storage ercot32 stays the keeper.", "file": "frontend/data/backcast/runs/2026-07-05-ercot33-storage-duration-gate.js", "id": "2026-07-05-ercot33-storage-duration-gate", "iso": "ERCOT", "label": "ercot33 storage duration gate", "shorthand": "ercot33-storage-duration-gate", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "ercot40 rtolcap-forward-v1 (P1-ONLY): ercot32 recipe EXACTLY + ercot_reserve_supply_forward=True \u2014 the RTOLCAP/RTOFFCAP reserve-supply cap is rebuilt from the WS-A forward formula (scarcity.ercot_rtolcap_forward_supply_cap_mw: derived per-class on-line headroom-realization shares \u00d7 the fleet's reserve-eligible capacity, keyed to the model's own forecast net-load, + the measured storage-AS term) instead of the measured ercot_<year>_ordc_reserves_hourly.parquet. The one delta (measured cap \u2192 formula cap) isolates the forward supply analogue; everything else is byte-for-byte ercot32. Identification gate (validate_ercot_rtolcap_forward.py) PASSED: coverage median ~2.08\u00d7 (not the ercot27 1.0\u00d7 exact-coverage artifact), RTOLCAP annual mean +11/-6/-12% 2023/24/25 (documented residuals: 2023 real-time scarcity depletion, 2025 storage/commitment growth beyond the fixed backcast base). Nothing on the path reads LMP/RTSPP/MCPC/RTORPA (honesty gate).", "file": "frontend/data/backcast/runs/2026-07-05-ercot40-rtolcap-forward.js", "id": "2026-07-05-ercot40-rtolcap-forward", "iso": "ERCOT", "label": "ercot40 rtolcap forward", "shorthand": "ercot40-rtolcap-forward", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-41-ct-evening-ablation", "date": "2026-07-05", "definition": "MISO 41 (KEEPER, supersedes miso-39): miso-40 de-leaked offer curve (neutral 1.0 generic gas bands, no inherited ERCOT multipliers) + CT_PEAKER reliability-floor EVENING WINDOW [15,21]. Fixes the C7/rule-13 D-4 failure carried by miso-39: the hot-day (tmax) CT reliability limb was floored a flat 38 MW in all 24 h (68-70% off-window, binding overnight when CT CF~0) because the MISO limb carried no sub-daily window; adding start_hour=15/end_hour=21 (matching the D-4 justified window [15,22) and the CAISO CT limbs) gates it to the afternoon-evening net-load ramp. RESULT: legitimacy diagnostics flip Overall FAIL->PASS (D-4 CT_PEAKER 0% off-window all 3 yrs; D-1/D-2/D-5/D-9 hold); zero new fitted parameter (the window is a structural shape param, derive-script-emitted). Mean LMP 28.67/25.99/34.47 (2023/24/25); vs miso-39 29.10/26.60/35.59 the de-leak trims prices ~0.4-1.1/MWh so C3a is modestly worse (-9.8/-15.6/-19.5% vs -8.5/-13.6/-16.9%), CO2 PASS x3 and the 0-h scarcity tail (C3c) unchanged. PROMOTED because strictly more structurally faithful: it clears a HARD legitimacy gate the incumbent violates (a rule-13 off-window floor) and removes the foreign ERCOT band leak, nothing tuned. OPEN ROOT CAUSES (logged, not fixed - rules #1/#11, results/calibration/FINDING-miso-burndown-2026-07.md): (A) coal (marginal ~94% of hours) is offered ~$4-5/MWh BELOW its measured F923 delivered SRMC by the gas-keyed passthrough sigmoid (model LMP $25.9 < coal committed measured SRMC $28.3 < actual $30.8 = coal econ_body measured $30.4), driving both the coal over-run (C1/C2) and the low price (C3a) - needs a measured take-or-pay-grounded bound on the marginal coal tranche, not a residual re-tune; (B) missing RDC/ELMP scarcity price (C3c). The neutral-1.0 gas committed bands sit AT the 1.0x SRMC floor (no rule-17 violation) and are immaterial since gas is never marginal - MISO does not need grounded gas bands as the burndown lever.", "file": "frontend/data/backcast/runs/2026-07-05-miso-41-ct-evening.js", "id": "2026-07-05-miso-41-ct-evening", "iso": "MISO", "label": "miso 41 ct evening", "market_story": "The evening-window CT_PEAKER reliability floor forces only 0.02-0.08 TWh/yr (<0.35% of the class) \u2014 a real but small hot-day evening-ramp reliability commitment, not a residual-buying floor. Zero-forcing every merchant floor confirms this directly: CT_PEAKER dispatch RISES 3.2/3.8/4.7% (2023/24/25) once the floor is removed, because it stops competing with floor-forced baseload for the same net-load hours, not falls, as a residual-buying floor would show. ST_GAS more than doubles (+63-115%) once other floors stop consuming load ahead of it. OTHER_FOSSIL's entire keeper volume (4.0/3.7/2.5 TWh/yr) disappears in the twin \u2014 that class is currently 100% floor-forced, an open root-cause item (rules #1/#11) to isolate, not fixed here. Coal subtypes and CC_REGULAR/CC_CHP move by <1.5%, confirming the keeper's floors are immaterial to the coal-vs-gas merit order the burndown finding (FINDING-miso-burndown-2026-07.md) already attributes to the passthrough-sigmoid offer curve, not to any floor.", "shorthand": "miso-41-ct-evening", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(CONTROL) A/B baseline for the neiso-48 CT-floor scrub: the identical neiso-47 recipe on current main with the two all-24h CT_PEAKER tmax reliability-floor limbs still ON. Documents the pre-scrub failing state the keeper removes \u2014 D-4 off-window binding 72-76% and C8 CT_PEAKER forced-energy share 0.47/0.78/0.47 (2023/24/25, gate <0.10). Not a keeper candidate; reference half of the neiso-48-ct-floor A/B.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-base-control.js", "id": "2026-07-05-neiso-48-base-control", "iso": "NEISO", "label": "neiso 48 base control", "shorthand": "neiso-48-base-control", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-05-neiso-48-ct-floor-ablation", "date": "2026-07-05", "definition": "KEEPER (promoted 2026-07-05, replacing neiso-47): the neiso-47 fast-start keeper recipe on current main with ONE structural change \u2014 the two all-24h CT_PEAKER temperature (tmax) reliability-floor limbs (Boston, Connecticut) SCRUBBED (enabled False in reliability_floor_coeffs_NEISO.csv), a zero-parameter mechanism deletion mirroring the caiso-52 CT scrub and the pjm-77 reconcile. Root cause (rules 17/18): the limbs carried no sub-daily window, so on any design-cooling day they forced fast-start CTs at min-stable for ALL 24 h; A/B vs the same-recipe control (neiso-48-base-control, bundle neiso_ctbase) shows D-4 off-window binding 72-76% -> floor removed, C8 CT_PEAKER forced-energy share 0.47/0.78/0.47 -> 0.00 all years, C7 off-peak CV ratio 0.65/0.63/0.59 -> 0.76/0.86/0.79. Disclosed cost (rule #1, NOT to be won back with a floor): CT_PEAKER grid volume falls to 0.010/0.021/0.099 TWh, absorbed by marginal CC_REGULAR at essentially the same price (dw-LMP +$0.02-0.06); every other class moves <0.0012 TWh. Remaining open C7 gate is ST_GAS diurnal shape (pre-existing in neiso-47, unchanged here) \u2014 the next NEISO root cause. Still NOT-YET. Promoted as the most structurally faithful NEISO run (rules #1/#12): one confirmed flat-floor bug removed, nothing tuned.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-ct-floor.js", "id": "2026-07-05-neiso-48-ct-floor", "iso": "NEISO", "label": "neiso 48 ct floor", "market_story": "ISO-NE fast-start peakers are economically dispatched for the afternoon/evening peak, not day-ahead committed at a floor: on hot days the real Boston/Connecticut CT fleet is near-zero overnight. The scrubbed all-24h limbs were forcing roughly half of the (tiny) CT_PEAKER class energy at binding floors and flattening its off-peak profile; removing them restores the spiky peaker signature while the marginal CC block absorbs the ~0.07-0.12 TWh/yr at the same clearing price.", "shorthand": "neiso-48-ct-floor", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(D-3 zero-forcing ablation twin of neiso-48-ct-floor, bundle neiso_ctscrub) every MERCHANT floor/bridge/drag off via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam, coal take-or-pay, measured biomass/OTHER must-run). Exact neiso-48 config/span (2023-2025, P1+P2). Registered per CLAUDE.md rule 20 so the keeper-vs-twin per-class delta is on the dashboard; not a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-ct-floor-ablation.js", "id": "2026-07-05-neiso-48-ct-floor-ablation", "iso": "NEISO", "label": "neiso 48 ct floor ablation", "shorthand": "neiso-48-ct-floor-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "HEAD re-gate (calibration-complete checklist item 1): byte-faithful replay of neiso-48-ct-floor meta.json at HEAD, all keeper years in one invocation, verifying reproducibility across the 07-04 offer merges per the pjm-77/nyiso-48 pattern.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-head-regate.js", "id": "2026-07-05-neiso-48-head-regate", "iso": "NEISO", "label": "neiso 48 head regate", "shorthand": "neiso-48-head-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper neiso_ctscrub (the 2026-07-05 neiso-48-ct-floor keeper, meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe (which replayed the prior neiso-47 keeper): the R2 physical-HR CO2 basis (fff2c34) moves NEISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is near-zero, per docs/handoffs/co2-keeper-regate-2026-07-05.md). Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-statmode-d7-r2.js", "id": "2026-07-05-neiso-statmode-d7-r2", "iso": "NEISO", "label": "neiso statmode d7 r2", "shorthand": "neiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-05-nyiso-47-ccdeleak-ablation", "date": "2026-07-05", "definition": "(PROBE, B-NYI-1, scalar remediation C-13/rule-25) NYISO de-leak: CC_REGULAR econ_high 1.21 -> 1.0 (ERCOT-cross-borrowed CC markup, retained only because removing it craters C3a ~ -24% = residual justification). CT_PEAKER 13.15x wall already de-leaked in source (0c6c833 / nyiso-42-band-deleak). C-17 Long_Island 0.45 LEFT unchanged (published Zone-K LCR is a peak-capacity ratio, not the all-hours energy self-supply frac; rule-14 boundary mismatch, issue #1345). Byte-faithful replay of nyiso-41 keeper mechanism set + source de-leak. EXPECTED C3a/price regression, recorded not chased (rule #1); C3a hole = issue #1344.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-47-ccdeleak.js", "id": "2026-07-05-nyiso-47-ccdeleak", "iso": "NYISO", "label": "nyiso 47 ccdeleak", "market_story": "Ablating the only NYISO merchant floor (nyiso_local_selfsupply, the Long Island LMIC floor) lets cheap NYC gas flood the cable-islanded LI pocket: LI in-zone thermal collapses toward the economic import-flooded solution the LP prefers, confirming the floor is what holds the ~8.5 TWh LI self-supply (the residual-identified 0.45 frac, rule-14 boundary-mismatch, issue #1345). Structural floors (firm HQ/Ontario imports, nuclear must-run, CHP steam, coal take-or-pay) are retained. The de-leaked CC econ band (econ_high 1.0) is unchanged between twin and probe, so the C3a hole is not a floor artifact \u2014 it is the missing NYISO reserve/scarcity price formation (issue #1344).", "shorthand": "nyiso-47-ccdeleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(D-3 zero-forcing ablation twin of nyiso_deleak_ccecon) every MERCHANT floor off (NYISO material floor: nyiso_local_selfsupply), structural protected set kept (nuclear must-run, CHP steam, coal take-or-pay, firm imports). Mirrors run_calibration_full.apply_zero_forcing_ablation.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-47-ccdeleak-ablation.js", "id": "2026-07-05-nyiso-47-ccdeleak-ablation", "iso": "NYISO", "label": "nyiso 47 ccdeleak ablation", "shorthand": "nyiso-47-ccdeleak-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 D-2 ATTRIBUTION TWIN of nyiso-48-head-regate, NOT a keeper) HEAD code (git 8d46b90) + keeper-era _NYISO_OFFER_CURVE restored via --offer-curve-json (CT_PEAKER peak 13.15/econ_low 1.27/econ_high 1.98, CC_REGULAR econ_high 1.21, CT_CHP 1.10/1.20/1.20/1.40) \u2014 the ONE delta vs nyiso-48. Determination NOT-YET (governance UNATTESTED; C8 pre-existing floor forced-share). RESULT: restoring only the offer curve recovers BOTH regressions \u2014 C1 free-class 10/10 (vs 48's 9/10), C7 diurnal (D-1) PASS (vs 48's FAIL; CT_PEAKER off-peak CV ratio 1.08/1.20/1.24 all pass), CT_PEAKER back to 1.56/1.37/1.75 TWh and ST_GAS to 7.86/9.67/11.08 (vs 48's 4.46/4.51/4.73 and 6.15/7.58/9.30). CONCLUSION: the entire nyiso-48 C1/C7 regression is the B-NYI-1 _NYISO_OFFER_CURVE de-leak, not the emissions R2 basis, interchange unification, or any other post-07-03 HEAD merge (residual CT_PEAKER delta vs keeper's 1.82 is ~0.26 TWh, negligible). This probe is a DIAGNOSTIC ONLY \u2014 it re-arms the de-leaked rule-25 scalars and MUST NOT be promoted (rule #26). The grounded (de-leaked) offer stays; the fix is structural (LI/NYC delivered-fuel basis + #1344 reserve scarcity). Rules #1/#17/#25/#26.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-49-offer-ab.js", "id": "2026-07-05-nyiso-49-offer-ab", "iso": "NYISO", "label": "nyiso 49 offer ab", "shorthand": "nyiso-49-offer-ab", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 real partial structural fix, NOT a keeper swap; keeper stays nyiso-41 STALE-VS-HEAD.) nyiso-41 keeper config at HEAD (de-leaked offer curve, = nyiso-48 baseline) + the new NYISO downstate CT interruptible city-gate gas premium (nyiso_downstate_ct_gas_basis), one-delta vs nyiso-48-head-regate, all years 2023-2025. MECHANISM (candidate a, issue #1344 / B-NYI-1): each NYC/Long Island CT_PEAKER (LM6000) unit's delivered gas is lifted from the Transco Z6 NY pipeline hub to its LDC city-gate delivered index by the MEASURED monthly premium (EIA NG N3050NY3 NY city-gate minus the measured Transco Z6 NY hub, floored 0; positive year-round mean ~$2.7/MMBtu, summer-peaked to ~$5). A rule-13 delivered fuel price: non-firm downstate peakers buy interruptible city-gate gas, so an HR~9-10 LM6000 no longer undercuts the HR~11-12 downstate steam fleet on flat hub gas. RESULT: CT_PEAKER 4.46/4.51/4.73 (nyiso-48) -> 3.26/4.20/4.03 TWh (actual 2.26/2.13/2.84); C1 CT_PEAKER FAIL->PASS 2023(+1.00)/2024(+2.06 TWh, in the +-2.94 band). C1 free-class stays 9/10 (remaining free fail = 2024 ST_GAS -3.39, the pre-existing steam/gas-total under-run, unchanged by the premium). C2/C4/C5a PASS. LIMITS (why still NOT a keeper): C7 (D-1) 2024 CT_PEAKER stays FAIL (off-peak cv_ratio 0.454->0.418<0.5) and C3a stays -17/-18/-15%. ROOT CAUSE of the residual: the LI CT over-run is DOMINATED by the Long Island local self-supply floor + CT temperature reliability floor forcing flat in-pocket LM6000 baseload (a fuel-cost premium cannot reduce floor-forced volume or restore diurnal peakiness), and the C3a under-price is the missing peaker competitive-scarcity / #1344 reserve-RCPF price structure (the reserve co-opt is present but binds only ~1000-2500 zone-hrs vs measured ~3000-4000). Candidate b (reserve/RCPF) EVALUATED: the published-tariff RCPF locational families are already in the LP (energy_reserve_coopt on) and cited, but confirmed non-binding with grounded static requirements (consistent with nyiso-29/30/31); the dearer downstate gas does not make them bind. The delivered-fuel basis is a validated, grounded, forward-reproducible structural input kept default-off; the residual is the floor re-derivation (rule #23, now that the basis has landed) + #1344. Rules #1/#3/#13/#26.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-50-downstate-ctgas.js", "id": "2026-07-05-nyiso-50-downstate-ctgas", "iso": "NYISO", "label": "nyiso 50 downstate ctgas", "shorthand": "nyiso-50-downstate-ctgas", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23), floors-alone config; one-delta vs nyiso-48 head-regate, all years 2023-2025. Two source-grounded narrowings: (1) the NYC CT_PEAKER 24h hot step (tmax 31.7 / 0.1833) DISABLED (r1_disabled) \u2014 the D-4 off-window binder that double-floored NYC CT on top of the windowed NYC_CT_ev ramp and bound all 24h incl. overnight where measured CAMPD NYC CT CF~=0.018 (rule 17/18); (2) the Long Island local self-supply floor NARROWED to the HB14-21 peak window (its LCR/cable-import driver binds only at the summer design-cooling peak, not overnight) \u2014 the 0.45 fraction (residual-identified, issue #1345) is UNCHANGED, only the hours it binds. RESULT: C7 diurnal (D-1) FAIL->PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 2.393). CT_PEAKER 4.46/4.51/4.73 -> 3.70/2.84/3.86 TWh (actual 2.26/2.13/2.84), C1 CT_PEAKER FAIL->in band; free-class stays 9/10 (remaining fail = 2024 ST_GAS -3.48, the pre-existing steam under-run). self-supply CT forcing HALVED (1.84/2.87/1.86 -> 0.90/1.23/0.89 TWh); reliability-floor CT overnight energy = 0.000 (was ~0.18 from the NYC step). NOT a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 25.6/34.1/25.1%) and C3a -16.2/-15.5/-13.6% / C3c 0/0/7h still FAIL \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure (CT peakers stay economically idle without it, so the floors carry the CT commitment). D-4 residual (~35%) is entirely hour 14 (0 overnight) \u2014 a boundary artifact between D-4's hardcoded canonical CT window h15-21 and the source-derived NYISO ramp HB14-21. Rules 1/17/18/23; #1344 out of scope (parallel LP-core refactor).", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-51-floor-rederive.js", "id": "2026-07-05-nyiso-51-floor-rederive", "iso": "NYISO", "label": "nyiso 51 floor rederive", "shorthand": "nyiso-51-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 KEEPER-CANDIDATE pending #1344, NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23) + nyiso_downstate_ct_gas_basis=True (the PR #1427 delivered-fuel city-gate premium, kept default-off); one-delta vs nyiso-48 head-regate + the floors config, all years 2023-2025. Floors: NYC CT 24h hot step DISABLED (r1_disabled, D-4 off-window binder) + LI local self-supply NARROWED to the HB14-21 peak window (0.45 level unchanged; hours only). RESULT: strongest candidate yet. CT_PEAKER 4.46/4.51/4.73 -> 2.02/2.33/2.91 TWh (actual 2.26/2.13/2.84) \u2014 near-exact all 3 years; C1 CT_PEAKER in band, free-class 9/10 (remaining fail = 2024 ST_GAS -3.30, the pre-existing steam under-run). C7 diurnal (D-1) PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 3.47, r 0.84). self-supply CT forcing halved; reliability-floor CT overnight energy = 0.000. NOT YET a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 45.8/54.5/39.3% \u2014 HIGHER share because the dearer downstate gas shrinks the economic-CT denominator) and C3a -13.5/-14.7/-12.5% (improved from -17/-18/-15 by the gas premium, still out of band) / C3c 0/0/7h \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure, the SAME root cause (CT peakers stay economically idle without it, so the floors carry the CT commitment and the tail never prices). D-4 residual (~34%) is entirely hour 14 (0 overnight) \u2014 the h15-21 vs HB14-21 window-boundary artifact, not off-window binding. Recommended eventual NYISO keeper config once #1344 lands. Rules 1/13/17/18/23; keeper stays nyiso-41 STALE-VS-HEAD, keepers.json unchanged.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-52-floor-rederive.js", "id": "2026-07-05-nyiso-52-floor-rederive", "iso": "NYISO", "label": "nyiso 52 floor rederive", "shorthand": "nyiso-52-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "D-7 statistical-mode A/B probe: byte-faithful replay of keeper nyiso41_hubprices (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe: the R2 physical-HR CO2 basis (fff2c34) moves NYISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is <0.1%, per docs/handoffs/co2-keeper-regate-2026-07-05.md). CAVEAT: this HEAD replay inherits the keeper's current offer state, including the B-NYI-1 `_NYISO_OFFER_CURVE` de-leak (CT_PEAKER peak 13.15->4.0, econ_low/econ_high 1.27/1.98->1.0/1.0; CC_REGULAR econ_high 1.21->1.0, merge a4c219e, 2026-07-05 re-gate) \u2014 recorded here, not compensated for; see docs/calibration-log.md 2026-07-05 NYISO keeper HEAD re-gate entry. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-statmode-d7-r2.js", "id": "2026-07-05-nyiso-statmode-d7-r2", "iso": "NYISO", "label": "nyiso statmode d7 r2", "shorthand": "nyiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-05-pjm-77-ct-relfloor-ablation", "date": "2026-07-05", "definition": "KEEPER (promoted 2026-07-05, replacing pjm-76): PJM 77 CT reliability-floor / net-load-drag reconcile: pjm-76 recipe VERBATIM on the rule-19 fix (drop_drag_owned_reliability_specs). The drag now owns CT_PEAKER commitment; the two all-day CT_PEAKER reliability limbs (EMAAC, West_APS) are dropped, clearing the D-4 off-window failure (97-99.7% off-window, all years) by removing the ~0.12 TWh overnight phantom the floor forced on hot days (measured CAMPD hot-day CT CF 0.0165 overnight vs 0.376 afternoon \u2014 the floor bound where its own driver says the class is offline, rule 17). No fitted parameter changed. Also carries the burndown's meta-gap fix (persist ct_netload_drag/ct_drag_overrides in meta.json), giving PJM its first ACCURATE legitimacy diagnostics \u2014 which honestly surface two pre-existing open items the gap had hidden: ct_netload_drag D-2 12.1% CT_PEAKER forced energy in 2024 (grounded mechanism vs the rule-20 budget in the tightest year; 2023 7.6% / 2025 7.9% pass) and CT_CHP D-4 off-window on its own all-24h cooling limb (0.0095 TWh; window/disable follow-up). Still NOT-YET. Promoted on structure (rules #1/17/19): a grounded floor removal plus honest diagnostics, not a fit move. See docs/FINDING-pjm-burndown-2026-07.md.", "file": "frontend/data/backcast/runs/2026-07-05-pjm-77-ct-relfloor.js", "id": "2026-07-05-pjm-77-ct-relfloor", "iso": "PJM", "label": "pjm 77 ct relfloor", "shorthand": "pjm-77-ct-relfloor", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE, not a keeper swap) PJM-77 demand-repair re-gate under PR #1426 (repaired demand-profile clean datatype). pjm-77 is the ONLY keeper whose scored years read the corrupted legacy eia_demand_profiles file (PJM has no per-BA demand extract; CAISO/MISO/NYISO/NEISO/ERCOT read dedicated per-BA hourly extracts for 2023-2025). The corruption was a zero-sentinel run: 23h in 2023 (idx 7393-7415) and 22h in 2024 (idx 1659-1680) at raw_mw=0.0; 2025 was already clean. TWIN A (resolve): byte-faithful pjm-77 meta.json replay at HEAD with the repaired demand engaged. Result: reproduces the committed keeper verdict CRITERION-FOR-CRITERION (NOT-YET; C1/C2/C3/C8 FAIL, C4/C5a/C7 PASS unchanged) \u2014 the only movement is the C6 governance gate showing UNATTESTED, a pure replay artifact (this bundle lacks the keeper's calibration_attestation.json; the LP dispatch is unchanged). Numeric deltas are tiny and confined to the two corrupted years: gas +0.38/+0.58 TWh, coal +0.11/+0.12 TWh (+~0.15%), CO2 +0.26/+0.34 Mt, mean LMP within 0.03 $/MWh, 2025 exactly zero (in-bundle control). No gate flips. Conclusion (rule #14): the demand repair is IMMATERIAL to every PJM scored criterion; pjm-77 is verified demand-robust and stays the keeper (NOT swapped to this confounded HEAD re-solve, which also carries ~30 files of post-e9daf7e code merges and lacks the governance attestation + zero-forcing ablation twin a keeper requires). Attribution twin B (HEAD + corrupted demand, isolated data root) decomposes A-B (demand repair) vs B-keeper (code merges) in docs/calibration-log.md 2026-07-05.", "file": "frontend/data/backcast/runs/2026-07-05-pjm-78-demand-regate.js", "id": "2026-07-05-pjm-78-demand-regate", "iso": "PJM", "label": "pjm 78 demand-regate", "shorthand": "pjm-78-demand-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-05-miso-41-ct-evening) D-3 zero-forcing ablation twin of the miso-41-ct-evening keeper (CLAUDE.md rule 20): the miso-41 recipe (de-leaked default offer curve + CT_PEAKER evening-window reliability floor) verbatim, same 2023-2025 span, with every merchant floor/bridge neutralized via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam-following, coal take-or-pay). Keeper-vs-twin per-class delta (real solved dispatch, not the D-2 fleet_only reconstruction): CT_PEAKER +3.2/+3.8/+4.7% (2023/24/25) \u2014 confirms the miso-41 evening-window floor is immaterial once fully removed, matching its own tiny 0.02-0.08 TWh/yr forced share; ST_GAS +115/+95/+63% \u2014 no longer crowded out once other floors stop consuming load; OTHER_FOSSIL -100% all years (4.0/3.7/2.5 TWh/yr to zero) \u2014 entirely floor-forced, an open root-cause item (rules #1/#11: which mechanism carries it is not yet isolated); coal subtypes -0.7% to -1.2%, CC_REGULAR/CC_CHP within \u00b10.4%. Registered alongside the keeper for the E9 keeper-vs-twin delta; not a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-06-miso-41-ct-evening-ablation.js", "id": "2026-07-06-miso-41-ct-evening-ablation", "iso": "MISO", "label": "miso 41 ct evening (ABLATION TWIN)", "shorthand": "miso-41-ct-evening-ablation", "years": [2023, 2024, 2025]}];